function travelView(){const a=guideAirport||T().airport,ap=airports[a],i=Math.min(T().step[a]||0,5);return title('EXPLORE WITH CONFIDENCE','ไปไหนกันดี','เลือกเส้นทาง ดูแผนที่ หรือเปิดประโยคให้คนช่วยอ่าน',btn(icon('pin')+' หลงทาง','lost','soft'))+`<div class="travelnav">${[['guide','สนามบิน','plane'],['routes','ขึ้นรถที่ไหน','travel'],['maps','แผนที่รถไฟ','plan'],['phrases','ภาษา','chat'],['immigration','เตรียม ตม.','file'],['manners','มารยาท','check']].map(([v,l,ic])=>`<button class="travelnav-item ${travelTab===v?'selected':''}" data-travel="${v}">${icon(ic)}<span>${l}</span></button>`).join('')}</div>${travelTab==='immigration'?immigrationView():travelTab==='manners'?mannersView():travelTab==='phrases'?phraseView():travelTab==='maps'?mapView():travelTab==='routes'?routeView():`<div class="tabs airport-tabs">${Object.entries(airports).map(([k,x])=>`<button class="tab ${a===k?'active':''}" data-airport="${k}"><b>${x.code}</b> ${x.name}</button>`).join('')}</div><div class="grid cols"><section class="card guidecard"><div class="cardhead"><span class="pill">${ap.name} · ${ap.city}</span><span class="muted">${i+1} / 6</span></div><div class="travel-sign">${steps[i][1]}</div><h2 class="guideheading">${steps[i][0]}</h2><p>${steps[i][2]}</p><div class="flex between">${btn('ย้อนกลับ','stepback')}${btn(i===5?'เลือกเส้นทางเข้าเมือง':'ทำแล้ว · ต่อไป','stepnext','primary')}</div><details><summary>เลือกขั้นตอนที่คุณอยู่</summary>${steps.map((s,j)=>`<button class="navbtn" data-step="${j}">${j+1}. ${s[0]}</button>`).join('')}</details><p class="note">อ้างอิง <a href="${ap.url}" target="_blank" rel="noopener">${ap.name}</a> · ตรวจ 29 ก.ย. 2026</p></section><div><section class="card"><span class="eyebrow">FIRST TIME IN JAPAN</span><h2 style="margin-top:10px">ของที่หยิบให้พร้อม</h2><div class="row">พาสปอร์ตตัวจริง ${icon('check')}</div><div class="row">ข้อมูลที่พักและเที่ยวบินขากลับ ${icon('check')}</div><div class="row">ข้อมูลสำแดง / เอกสารเข้าเมือง ${icon('check')}</div><p class="note">เปิดจากกระเป๋าทริปได้ แม้ยังไม่ได้เปิดซิม</p><button class="btn full soft" data-page="trip">เปิดกระเป๋าทริป</button></section><section class="card gap"><h2>ถามเจ้าหน้าที่ได้เลย</h2><p>ไม่มั่นใจว่าต้องไปไหน? เปิดประโยคภาษาญี่ปุ่นให้เจ้าหน้าที่อ่าน</p>${btn('เปิดประโยคถามทาง','phrase','full','data-index="10"')}</section></div></div>`}`}
function routeView(){const list=routeGuides.filter(r=>r.city===routeCity);if(!list.some(r=>r.id===routeId))routeId=list[0].id;const r=list.find(r=>r.id===routeId),online='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(r.from.replace(' / Terminal 2·3',''))+'&destination='+encodeURIComponent(r.to+' station Japan')+'&travelmode=transit';return `<div class="cityswitch"><button class="${routeCity==='tokyo'?'active':''}" data-route-city="tokyo">東京 <span>โตเกียว</span></button><button class="${routeCity==='osaka'?'active':''}" data-route-city="osaka">大阪 <span>โอซาก้า</span></button></div><div class="grid cols"><section class="card routecard">${select('คุณจะเดินทางจากไหน ไปที่ไหน?','routeChoice',list.map(x=>[x.id,x.origin+' → '+x.destination]),routeId)}<div class="linebadge" style="--rail:${r.color}">${icon('travel')} ${r.line}</div><div class="stationpath" style="--rail:${r.color}"><div><small>ขึ้นที่</small><strong>${r.from}</strong><span>${r.origin}</span></div><div><small>ลงที่</small><strong>${r.to}</strong><span>${r.destination}</span></div></div><div class="direction"><span>ดูป้ายขบวนไปทาง</span><b>${r.direction}</b></div><div class="routesteps">${[['หาจุดขึ้นรถ',r.board],['เตรียมตั๋ว',r.ticket],['ขึ้นขบวนนี้',r.ride],['ลงแล้วไปต่อ',r.finish]].map(([h,p],j)=>`<div class="stepcard"><span class="stepnum">${j+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><div class="flex gap">${link('ดูเที่ยวรถตอนนี้',online)}${btn('บันทึกลงแผนเที่ยว','saveroute','primary')}</div><p class="note">เส้นทางตัวอย่างที่ตรวจสอบแล้ว ไม่ใช่เวลารถสด · เลขชานชาลาให้ดูจากจอวันเดินทาง<br><a href="${r.source}" target="_blank" rel="noopener">ข้อมูลผู้ให้บริการ</a> · ตรวจ 29 ก.ย. 2026</p></section><div><section class="card"><h2>ไปที่อื่น?</h2><p class="note">ใส่ชื่อสถานีหรือโรงแรม เพื่อเปิดเส้นทางรถสาธารณะปัจจุบัน</p><form id="transitSearch">${field('เริ่มต้น','origin',r.origin,'text','required')}${field('ปลายทาง','destination','','text','required placeholder="เช่น Tokyo Disneyland"')}<button class="btn primary full" type="submit">ค้นเส้นทางออนไลน์</button></form></section><section class="card gap"><h2>ดูภาพรวมก่อนขึ้นรถ</h2><p>แผนที่รถใต้ดินและเครือข่ายรถไฟ เลือกดูแยกตามเมืองได้</p>${btn('เปิดแผนที่รถไฟ','showmaps','full soft')}</section></div></div>`}
function translateURL(text='',from='th',to='ja'){return 'https://translate.google.com/?sl='+from+'&tl='+to+'&text='+encodeURIComponent(text)+'&op=translate'}
function phraseView(){return `<section class="phraseintro"><div><span class="eyebrow">POCKET CONVERSATIONS</span><h2>อยากพูดอะไร?</h2><p>${phrases.length} ประโยค · เสียงญี่ปุ่นและอังกฤษ · คำอ่านไทย</p></div><span class="phrasekanji" aria-hidden="true">話</span></section>${translatorPanel()}<section class="translatebar"><div><strong>ให้เขาพิมพ์ตอบกลับได้เลย</strong><span>เปิด Google Translate · ใช้อินเทอร์เน็ต</span></div><div class="flex">${link('ไทย → ญี่ปุ่น',translateURL())}${link('ญี่ปุ่น → ไทย',translateURL('','ja','th'))}${link('อังกฤษ → ไทย',translateURL('','en','th'))}</div></section><div class="phrase-tools"><label class="field"><span class="sr-only">ค้นหาประโยค</span><input id="phraseSearch" type="search" placeholder="ค้นหา เช่น ขอหนึ่งที่ ตัวเลข ห้องน้ำ…" value="${esc(phraseQuery)}"></label><div class="language-toggle" aria-label="ภาษาที่แสดง">${[['ja','日本語 ญี่ปุ่น'],['en','English อังกฤษ']].map(([v,l])=>`<button type="button" data-phrase-lang="${v}" aria-pressed="${phraseLanguage===v}">${l}</button>`).join('')}</div></div><div class="categoryrail">${['ปักหมุด','ทั้งหมด',...new Set(phrases.map(p=>p[0]))].map(c=>`<button class="category ${phraseCategory===c?'selected':''}" data-phrase-category="${c}">${c}</button>`).join('')}</div><p class="note">คำอ่านไทยเป็นเสียงโดยประมาณ · ตัวเลขกับการนับชิ้น/คนใช้คำต่างกัน · เลือกภาษาไหน ปุ่มฟังจะอ่านภาษานั้น</p><div id="phraseResults" class="grid two">${phraseResults()}</div>`}
function phraseResults(){const results=phrases.map((p,i)=>({p,i})).filter(({p,i})=>(phraseCategory==='ปักหมุด'?(T().favorites||[]).includes(i):(phraseCategory==='ทั้งหมด'||p[0]===phraseCategory))&&p.join(' ').toLowerCase().includes(phraseQuery.toLowerCase()));return results.length?results.map(({p,i})=>`<article class="phrasecard"><div class="flex between"><span class="phrasecat">${p[0]}</span>${btn((T().favorites||[]).includes(i)?'★ ปักแล้ว':'☆ ปักหมุด','pinphrase','small',`data-index="${i}" aria-pressed="${(T().favorites||[]).includes(i)}"`)}<button class="sound-icon" data-action="speakphrase" data-index="${i}" data-lang="${phraseLanguage}" aria-label="ฟัง${phraseLanguage==='en'?'อังกฤษ':'ญี่ปุ่น'} ${esc(p[1])}">${speaker()}</button></div><h3>${p[1]}</h3><p class="phrasejp ${phraseLanguage==='en'?'phrase-en':''}" lang="${phraseLanguage}">${p[phraseLanguage==='en'?3:2]}</p><p class="reading">${p[phraseLanguage==='en'?6:4]}</p>${phraseLanguage==='ja'?`<p class="romaji">${p[5]}</p>`:''}<details class="alternate-language"><summary>${phraseLanguage==='ja'?'อังกฤษ + คำอ่าน':'ญี่ปุ่น + คำอ่าน'}</summary><p lang="${phraseLanguage==='ja'?'en':'ja'}">${p[phraseLanguage==='ja'?3:2]}</p><p class="reading">${p[phraseLanguage==='ja'?6:4]}</p></details><div class="phrasebottom">${btn('ขยายประโยค','phrase','small',`data-index="${i}"`)}${btn('ฟังช้า ๆ','speakslow','small soft',`data-index="${i}" data-lang="${phraseLanguage}"`)}</div></article>`).join(''):'<div class="empty">ไม่พบประโยค ลองคำสั้น ๆ หรือเลือกหมวดทั้งหมด</div>'}
function speaker(){return '<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M11 4 6 8H2v8h4l5 4V4ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/></svg>'}
function phraseModal(i){const p=phrases[i];if(!p)return;modal(p[1],`<div class="fullscreenjp"><span class="language-label">日本語 · ญี่ปุ่น</span><p class="jp" lang="ja">${p[2]}</p><p class="reading">${p[4]}</p><p class="romaji">${p[5]}</p><div class="english-block"><span class="language-label">ENGLISH · อังกฤษ</span><p lang="en">${p[3]}</p><p class="reading">${p[6]}</p></div></div><div class="flex">${btn(speaker()+' ญี่ปุ่น','speakphrase','primary',`data-index="${i}" data-lang="ja"`)}${btn(speaker()+' อังกฤษ','speakphrase','soft',`data-index="${i}" data-lang="en"`)}${btn('ฟังช้า · '+(phraseLanguage==='en'?'อังกฤษ':'ญี่ปุ่น'),'speakslow','soft',`data-index="${i}" data-lang="${phraseLanguage}"`)}${btn('หยุด','stopspeech')}</div><p class="note" id="voiceStatus">ดาวน์โหลดชุดออฟไลน์เพื่อฟังได้เมื่อไม่มีเน็ต</p><div class="flex">${link('แปลประโยคนี้ต่อ',translateURL(p[2],'ja','th'))}${link('ให้เขาพิมพ์ตอบ',translateURL('','ja','th'))}</div><p class="note">ลิงก์แปลภาษาใช้เน็ต</p>`)}
let phraseAudio=null;
function stopPhraseAudio(){if(phraseAudio){phraseAudio.pause();phraseAudio.currentTime=0}document.querySelectorAll('[data-action="speakphrase"],[data-action="speakslow"]').forEach(b=>b.classList.remove('playing'));}
function speakPhrase(i,slow=false,lang=phraseLanguage){lang=lang==='en'?'en':'ja';if(!Number.isInteger(i)||!phrases[i])return;stopPhraseAudio();const player=new Audio(new URL('audio/'+lang+'-'+String(i).padStart(3,'0')+'.mp3',document.baseURI).href);phraseAudio=player;player.preload='auto';player.playbackRate=slow?.8:1;player.preservesPitch=true;player.volume=1;const status=m=>{if($('#voiceStatus'))$('#voiceStatus').textContent=m};player.onplaying=()=>{status((slow?'กำลังอ่านช้า · ':'กำลังอ่าน · ')+(lang==='en'?'อังกฤษ':'ญี่ปุ่น'));document.querySelectorAll('[data-index="'+i+'"][data-action="'+(slow?'speakslow':'speakphrase')+'"]').forEach(b=>b.classList.add('playing'))};player.onended=()=>{status('อ่านจบแล้ว กดฟังซ้ำได้');document.querySelectorAll('.playing').forEach(b=>b.classList.remove('playing'))};player.onerror=()=>{status('โหลดเสียงไม่สำเร็จ');toast(navigator.onLine?'โหลดเสียงไม่ได้ ลองรีเฟรชหน้าแล้วกดฟังอีกครั้ง':'เสียงนี้ยังไม่ได้ดาวน์โหลด กรุณาเชื่อมต่อเน็ตแล้วกดเตรียมออฟไลน์')};status('กำลังโหลดเสียง…');player.play().catch(e=>{if(e.name==='AbortError')return;status('ยังเล่นเสียงไม่ได้');toast('เปิดเว็บใน Chrome หรือ Safari แล้วกดฟังอีกครั้ง และตรวจระดับเสียงสื่อ')});}
function mapView(){return `<div class="cityswitch"><button class="${mapCity==='tokyo'?'active':''}" data-map-city="tokyo">東京 <span>โตเกียว</span></button><button class="${mapCity==='osaka'?'active':''}" data-map-city="osaka">大阪 <span>โอซาก้า & คันไซ</span></button></div><div class="maptip"><b>อ่านแผนที่ง่าย ๆ</b><span>หาสถานีต้นทาง → ตามสีสาย → ดูจุดเปลี่ยนสาย → หาสถานีปลายทาง</span></div><div class="grid two">${railMaps.filter(m=>m.city===mapCity).map(m=>`<article class="card mapcard"><button class="mapthumb" data-action="openmap" data-map="${m.id}" aria-label="ขยายแผนที่ ${m.title}"><img src="maps/${m.id}.webp" alt="${m.title} แผนที่ทางการ" loading="lazy"></button><h2>${m.title}</h2><p>${m.subtitle}</p><div class="flex">${btn('ขยายแผนที่','openmap','primary',`data-map="${m.id}"`)}<a class="btn" href="maps/${m.id}.pdf" download>เก็บ PDF</a></div><p class="note">${m.credit}<br><a href="${m.source}" target="_blank" rel="noopener">แหล่งที่มา / ฉบับล่าสุด</a> · ตรวจ 29 ก.ย. 2026</p></article>`).join('')}</div><section class="card gap"><h2>รู้จักสีและรหัสสถานี</h2><p>ตัวอักษรคือสายรถไฟ ตัวเลขคือสถานี ตัวอย่าง M16 Umeda และ M20 Namba อยู่บน Midosuji สายเดียวกัน แผนที่ Metro ไม่ใช่ตั๋วรวม JR หรือรถไฟสนามบินทุกสาย</p><button class="btn soft" data-travel="routes">เลือกเส้นทางพร้อมวิธีขึ้น–ลง</button></section>`}
let mapScale=1;
function openMap(id){const m=railMaps.find(m=>m.id===id);mapScale=1;$('#modal').classList.add('mapmodal');modal(m.title,`<div class="flex maptools">${btn('−','mapminus','','aria-label="ย่อแผนที่"')}${btn('+','mapplus','','aria-label="ขยายแผนที่"')}${btn('พอดีจอ','mapreset')}<a class="btn" href="maps/${m.id}.pdf" target="_blank" rel="noopener">เปิด PDF</a><span class="note">ขยายแล้วเลื่อนดูได้</span></div><div class="mapviewport"><img id="mapImage" src="maps/${m.id}.webp" alt="${m.title}" style="width:100%;max-width:none"></div><p class="note">${m.credit}</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.routeCity){routeCity=b.dataset.routeCity;render()}if(b.dataset.mapCity){mapCity=b.dataset.mapCity;render()}if(b.dataset.phraseLang){phraseLanguage=b.dataset.phraseLang;render()}if(b.dataset.phraseCategory){phraseCategory=b.dataset.phraseCategory;render()}switch(b.dataset.action){case'speakphrase':speakPhrase(+b.dataset.index,false,b.dataset.lang||phraseLanguage);break;case'speakslow':speakPhrase(+b.dataset.index,true,b.dataset.lang||phraseLanguage);break;case'stopspeech':stopPhraseAudio();break;case'showmaps':travelTab='maps';mapCity=routeCity;render();break;case'openmap':openMap(b.dataset.map);break;case'mapplus':case'mapminus':case'mapreset':mapScale=b.dataset.action==='mapreset'?1:Math.min(5,Math.max(1,mapScale+(b.dataset.action==='mapplus'?.5:-.5)));$('#mapImage').style.width=mapScale*100+'%';break;case'saveroute':{const r=routeGuides.find(r=>r.id===routeId);eventModal();$('#eventform [name=title]').value=r.origin+' → '+r.destination;$('#eventform [name=note]').value=r.line+'\nขึ้น: '+r.from+'\nลง: '+r.to+'\nทิศทาง: '+r.direction+'\n'+r.ticket;break}}});
document.addEventListener('input',e=>{if(e.target.id==='phraseSearch'){phraseQuery=e.target.value;$('#phraseResults').innerHTML=phraseResults()}});
document.addEventListener('change',e=>{if(e.target.name==='routeChoice'){routeId=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='transitSearch'){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));const u='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(v.origin+' Japan')+'&destination='+encodeURIComponent(v.destination+' Japan')+'&travelmode=transit';window.open(u,'_blank','noopener,noreferrer')}});
$('#modal').addEventListener('close',()=>{$('#modal').classList.remove('mapmodal');stopPhraseAudio()});


function mannersView(){return `<section class="section-lead"><span class="eyebrow">SMALL THINGS, BIG RESPECT</span><h2>เที่ยวอย่างเข้าใจคนท้องถิ่น</h2><p>12 เรื่องที่ควรรู้ ใช้ได้ทั้งโตเกียวและโอซาก้า<br>สังเกตป้ายและกติกาของแต่ละสถานที่เป็นหลัก</p></section><div class="grid two manners-grid">${etiquette.map(([c,no,yes,ic],i)=>`<article class="card manners-card"><div class="flex between"><span class="pill">${c}</span><span class="muted">${String(i+1).padStart(2,'0')}</span></div><h3>${icon(ic)} ${no}</h3><div class="do-instead"><b>ทำแบบนี้แทน</b><p>${yes}</p></div></article>`).join('')}</div><section class="card gap"><h3>ไม่แน่ใจ? ถามสุภาพไว้ก่อน</h3><p>すみません。 · สุมิมะเซ็น · Excuse me. / เอ็กซ์คิวส์ มี</p>${btn('เปิดประโยคถามเรื่องมารยาท','mannersphrases','soft')}<details><summary>แหล่งข้อมูล · ตรวจ 29 ก.ย. 2026</summary><p><a href="https://www.japan.travel/en/responsible-travel-guide/japanese-customs-and-etiquette/" target="_blank" rel="noopener">JNTO · ธรรมเนียมและมารยาท</a><br><a href="https://www.westjr.co.jp/travel-information/en/train-usage-guide/howto/manners/" target="_blank" rel="noopener">JR West · มารยาทบนรถไฟ</a><br><a href="https://www.japan.travel/en/responsible-travel-guide/traveling-mindfully/" target="_blank" rel="noopener">JNTO · การใช้พื้นที่สาธารณะ</a><br><a href="https://www.japan.travel/en/guide/japanese-food-etiquette/" target="_blank" rel="noopener">JNTO · การใช้ตะเกียบ</a><br><a href="https://www.japan.travel/en/responsible-travel-guide/features/responsible-photography/" target="_blank" rel="noopener">JNTO · การถ่ายภาพ</a></p></details></section>`}
function immigrationView(){const t=T();return `<section class="section-lead"><span class="eyebrow">ARRIVE WITH CONFIDENCE</span><h2>เตรียมตอบ ตม. อย่างมั่นใจ</h2><p>ฝึกฟังคำถาม อ่านคำตอบสั้น ๆ แล้วปรับให้ตรงกับทริปจริงของคุณ</p></section><div class="notice">เป็นแนวฝึกภาษา ไม่ใช่รายการคำถามตายตัวหรือการรับรองผ่านเข้าเมือง ตอบตามจริงและตามเอกสารเสมอ</div><div class="grid cols"><div><div class="cardhead"><h2>ถามอะไร · ตอบอย่างไร</h2><span class="pill">${immigrationQA.length} หัวข้อ</span></div>${immigrationQA.map((q,i)=>`<details class="qa-card" ${i===0?'open':''}><summary><span class="qa-number">${String(i+1).padStart(2,'0')}</span><span>${q[1]}<small lang="en">${q[2]}</small></span></summary><div class="qa-body"><span class="language-label">คำอ่านคำถาม</span><p class="reading">${q[3]}</p><div class="answer-box"><span class="language-label">ตัวอย่างคำตอบ</span><p lang="en">${q[4]}</p><p class="reading">${q[5]}</p><p class="note">${q[6]}</p></div>${t.immigration?.[q[0]]?`<div class="my-answer"><span class="language-label">คำตอบที่คุณเตรียมไว้</span><p>${esc(t.immigration[q[0]])}</p></div>`:''}<div class="flex">${btn('เขียนคำตอบของฉัน','qaedit','small',`data-qa="${i}"`)}${link('แปลเป็นไทย',translateURL(t.immigration?.[q[0]]||q[4],'auto','th'))}${link('แปลเป็นอังกฤษ',translateURL(t.immigration?.[q[0]]||q[4],'auto','en'))}</div></div></details>`).join('')}</div><div><section class="card prep-docs"><h2>เตรียมหยิบให้พร้อม</h2><p>พาสปอร์ต · ที่อยู่และใบจองที่พัก · ตั๋วขากลับ · แผนเที่ยว</p><button class="btn full soft" data-page="trip">เปิดเอกสารและที่พัก</button><p class="note">ทริปนี้: ${formatDate(t.start)} – ${formatDate(t.end)}<br>นับวันพักจากวันเข้า–ออกญี่ปุ่น ไม่รวมคืนบินจากไทย</p><p class="note">ยืนยันที่พักคืนแรกให้เรียบร้อย หากเปลี่ยนโรงแรม ให้เตรียมการจองทุกคืน</p>${link('Visit Japan Web ทางการ','https://services.digital.go.jp/en/visit-japan-web/')}<p class="note">บริการเตรียมข้อมูลเข้าเมืองและศุลกากรออนไลน์<br><a href="https://www.digital.go.jp/en/policies/visit_japan_web" target="_blank" rel="noopener">Digital Agency</a> · ตรวจ 29 ก.ย. 2026</p></section><section class="card gap"><h2>ฟังไม่ทัน ไม่ต้องเดา</h2><p>ขอให้พูดช้า เขียนให้ดู หรือถามว่ามีล่ามภาษาไทยไหม</p>${btn('เปิดประโยคช่วยสื่อสารกับ ตม.','immigrationphrases','full soft')}${link('เปิดแปลภาษาอังกฤษ → ไทย',translateURL('','en','th'))}</section></div></div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;switch(b.dataset.action){case'mannersphrases':phraseCategory='มารยาท';travelTab='phrases';phraseQuery='';render();break;case'immigrationphrases':phraseCategory='ตม. / เข้าเมือง';travelTab='phrases';phraseQuery='';render();break;case'qaedit':{const q=immigrationQA[+b.dataset.qa];formModal('คำตอบของฉัน · '+q[1],'qaform',`<input type="hidden" name="key" value="${q[0]}"><p lang="en">${q[2]}</p>${textarea('ใส่คำตอบตามข้อมูลจริงของคุณ','answer',T().immigration?.[q[0]]||'')}<p class="note">พิมพ์ไทยหรืออังกฤษได้ บันทึกแยกตามทริปในเครื่องนี้</p>`);break}}});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='qaform')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),t=T(),old=t.immigration;t.immigration={...old,[v.key]:v.answer.trim()};if(save()){$('#modal').close();render();toast('เก็บคำตอบสำหรับทริปนี้แล้ว')}else t.immigration=old});

let walletDraft=null,walletFilter='all',walletQuery='',walletMessage='';
const walletTypes={expense:'รายจ่าย',income:'รายรับ',cash:'เติม / ลดเงินสด',settle:'คืนเงินระหว่างกัน'};
const expenseCategories=['ตั๋วเครื่องบิน','รถไป–กลับสนามบิน','ประกัน','ซิม / อินเทอร์เน็ต','อาหาร','เดินทาง','ที่พัก','ตั๋วเที่ยว','ซื้อของ','อื่น ๆ'];
function walletEntries(){const t=T();return [...t.expenses.map(x=>({...x,source:'expense',kind:x.amount<0?'refund':'expense'})),...t.moves.map(x=>({...x,source:'move',rate:x.rate||t.rate,title:x.title||(x.kind==='income'?'รายรับ':x.kind==='cash'?'ปรับเงินสด':'คืนเงินระหว่างกัน')}))].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''))}
function walletList(){const rows=walletEntries().filter(x=>(walletFilter==='all'||(walletFilter==='movement'?['cash','settle','refund'].includes(x.kind):x.kind===walletFilter))&&(x.title+' '+(x.category||'')+' '+x.date).toLowerCase().includes(walletQuery.toLowerCase()));if(!rows.length)return `<div class="wallet-empty">${icon('money')}<h3>${walletQuery||walletFilter!=='all'?'ไม่พบรายการที่เลือก':'เริ่มบัญชีทริปของคุณ'}</h3><p>${walletQuery||walletFilter!=='all'?'ลองคำค้นอื่นหรือเลือกทั้งหมด':'จดค่ากิน ค่าเดินทาง หรือเงินที่ได้รับ<br>ยอดเยนและบาทจะคำนวณให้ทันที'}</p>${btn('บันทึกรายจ่ายแรก','expense','primary')}</div>`;let previous='';return rows.map(e=>{const date=e.date!==previous?`<div class="ledger-date">${formatDate(e.date)}<span>${e.date===today()?'วันนี้':''}</span></div>`:'';previous=e.date;const positive=e.kind==='income'||e.kind==='refund'||e.kind!=='expense'&&e.amount>0;return date+`<article class="ledger-row"><span class="ledger-icon ${positive?'incoming':''}">${icon(e.category==='ซื้อของ'?'shop':e.kind==='expense'?'money':'download')}</span><div class="ledger-description"><h3>${esc(e.title)}</h3><p>${esc(walletTypes[e.kind]||'รับคืนจากร้าน')} · ${e.method==='cash'?'เงินสด':'บัตร / บัญชี'}</p>${e.kind==='expense'?`<small>${esc(T().people[payerIndex(e)]||'ไม่ระบุ')} จ่าย · ส่วนฉัน ${e.currency==='THB'?thb(e.mine*e.rate):jpy(e.mine)}</small>`:''}</div><div class="ledger-amount ${positive?'incoming':''}"><strong>${positive?'+':'−'}${nativeMoney(e)}</strong><small>≈ ${e.currency==='THB'?jpy(Math.abs(e.amount)):thb(Math.abs(e.amount)*e.rate)}</small><button type="button" class="linkbtn" data-action="walletedit" data-source="${e.source}" data-id="${e.id}">ดู / แก้ไข</button></div></article>`}).join('')}
function moneyView(){if(moneyTab==='summary')return tripSummaryView();if(moneyTab==='entry')return walletEntryView();if(moneyTab!=='ledger')return legacyMoneyView();const t=T(),z=totals(),pct=t.budget?Math.max(0,Math.min(100,z.cost/t.budget*100)):0;return title('MY TRAVEL WALLET','บัญชีทริป',esc(t.name)+' · บันทึกในเครื่อง ใช้ได้ออฟไลน์')+`<div class="wallet-tabs">${[['ledger','รายรับ–รายจ่าย'],['summary','รวมทั้งทริป'],['convert','แปลงเงิน'],['shop','ส่วนลด & Tax-free']].map(([v,l])=>`<button type="button" class="${moneyTab===v?'active':''}" data-money="${v}">${l}</button>`).join('')}</div>${walletMessage?`<div class="wallet-success" role="status">${icon('check')}<span>${esc(walletMessage)}</span><button type="button" data-action="walletdismiss" aria-label="ปิดข้อความ">×</button></div>`:''}<div class="wallet-layout"><div><section class="wallet-overview"><div class="flex between"><span>รายจ่ายส่วนของฉัน</span><span class="wallet-currency">THB</span></div><div class="wallet-total">${thb(z.cost)}</div><p>คำนวณจากส่วนแบ่งและเรทของแต่ละรายการ</p><div class="wallet-metrics"><div><span>รายรับของฉัน</span><strong>${thb(z.income)}</strong></div><div><span>วันนี้ใช้ไป</span><strong>${thb(z.dayCost)}</strong></div></div></section><div class="wallet-main-actions">${btn(icon('plus')+' รายจ่าย','expense','primary')}${btn(icon('plus')+' รายรับ','walletincome','income-btn')}</div><div class="wallet-small-stats"><section><span>เงินสดเยนในมือ</span><strong>${jpy(z.cash)}</strong><small>≈ ${thb(z.cash*t.rate)}</small>${btn('เติม / ลดเงินสด','cash','small')}</section><section><span>${z.debt>=0?'เพื่อนต้องคืนฉัน':'ฉันต้องคืนเพื่อน'}</span><strong>${jpy(Math.abs(z.debt))}</strong><small>${z.debtTHB>=0?'รับคืน':'คืนเพื่อน'} ${thb(Math.abs(z.debtTHB))} แยกยอดบาท</small>${btn('จดการคืนเงิน','settle','small')}</section></div><section class="wallet-budget"><div class="flex between"><h3>งบส่วนตัว</h3>${btn('ตั้งงบ','tripsettings','small')}</div><p>${t.budget?`เหลือ <b>${thb(z.remaining)}</b> จาก ${thb(t.budget)}`:'ยังไม่ตั้งงบ ก็เริ่มจดรายรับ–รายจ่ายได้'}</p>${t.budget?`<div class="bar"><i style="width:${pct}%"></i></div>`:''}<small>รายรับและการเติมเงินสดไม่เปลี่ยนงบที่คุณตั้งไว้</small></section></div><section class="card wallet-ledger"><div class="cardhead"><h2>รายการทั้งหมด</h2><span class="pill">${walletEntries().length} รายการ</span></div><label class="field"><span class="sr-only">ค้นหารายการ</span><input id="walletSearch" type="search" value="${esc(walletQuery)}" placeholder="ค้นหารายการ เช่น อาหาร รถไฟ…"></label><div class="ledger-filters">${[['all','ทั้งหมด'],['expense','รายจ่าย'],['income','รายรับ'],['movement','ย้าย / คืนเงิน']].map(([v,l])=>`<button type="button" data-wallet-filter="${v}" aria-pressed="${walletFilter===v}">${l}</button>`).join('')}</div><div id="walletRows">${walletList()}</div><div class="wallet-tools">${btn('สรุป / ส่งออกค่าใช้จ่าย','summary','small')}${btn('รับคืนจากร้าน / Tax-free','refund','small')}${btn(icon('trash')+' รายการที่ลบ','wallettrash','small')}</div></section></div>`}
function openWalletEntry(kind='expense',id='',prefill={}){const t=T();const source=kind==='expense'?'expense':'move',old=(source==='expense'?t.expenses:t.moves).find(e=>e.id===id);walletDraft={recordId:id,tripId:t.id,kind:old?.kind||kind,label:old?.title||prefill.title||'',amount:old?Math.abs(old.currency==='THB'?old.amount*old.rate:old.amount):prefill.amount??'',currency:old?.currency||prefill.currency||'JPY',phase:old?.phase||prefill.phase||'auto',category:old?.category||prefill.category||(kind==='income'?'รายรับอื่น ๆ':'อาหาร'),split:old?.split||prefill.split||'mine',mine:old?(old.currency==='THB'?old.mine*old.rate:old.mine):'',payer:old?.payer||'me',payment:old?.method||'cash',date:old?.date||today(),rate:old?.rate||t.rate,note:old?.note||'',direction:old&&old.amount<0?'out':'in'};if(kind==='settle'&&!old){const n=totals().debt;walletDraft.amount=Math.abs(n)||'';walletDraft.direction=n>=0?'in':'out'}page='money';moneyTab='entry';location.hash='money';render();scrollTo(0,0)}
function walletEntryView(){const v=walletDraft,t=T();if(!v){moneyTab='ledger';return moneyView()}const expense=v.kind==='expense',cash=v.kind==='cash',settle=v.kind==='settle';return `<div class="wallet-editor-heading">${btn('กลับบัญชีทริป','walletcancel','soft')}<span class="pill">บันทึกออฟไลน์ได้</span></div><div class="wallet-editor"><div class="editor-title"><span class="eyebrow">${v.recordId?'EDIT TRANSACTION':'NEW TRANSACTION'}</span><h1>${v.recordId?'แก้ไข':'บันทึก'}${walletTypes[v.kind]}</h1></div><form id="walletform" novalidate><input type="hidden" name="recordId" value="${esc(v.recordId)}"><input type="hidden" name="kind" value="${v.kind}"><div class="entry-type-picker">${Object.entries(walletTypes).map(([k,l])=>`<button type="button" data-wallet-kind="${k}" aria-pressed="${k===v.kind}" ${v.recordId?'disabled':''}>${l}</button>`).join('')}</div><div id="walletError" class="formerror" role="alert" hidden></div><div class="wallet-entry-columns"><section><div class="amount-entry ${v.kind==='income'?'income-entry':''}">${select('สกุลเงินที่จ่ายจริง','currency',(cash?[['JPY','เยน (JPY)']]:[['JPY','เยน (JPY)'],['THB','บาท (THB)']]),v.currency)}${field('ยอดเงิน','amount',v.amount,'text','inputmode="decimal" autocomplete="off" placeholder="0" aria-describedby="walletPreview"')}<div id="walletPreview" aria-live="polite"></div></div>${field('ชื่อรายการ','label',v.label,'text','maxlength="120" placeholder="'+(expense?'เช่น อาหารกลางวัน':v.kind==='income'?'เช่น รายได้ระหว่างทริป':'ใส่รายละเอียดสั้น ๆ')+'"')}<p class="note">เว้นว่างได้ ระบบจะใช้ชื่อหมวดให้</p>${expense||v.kind==='income'?select('หมวด','category',(expense?expenseCategories:['รายรับอื่น ๆ','รายได้','ของขวัญ']).map(c=>[c,c]),v.category):''}${cash||settle?select('ทิศทาง','direction',settle?[['in','เพื่อนคืนฉัน'],['out','ฉันคืนเพื่อน']]:[['in','เติม / ถอนเงินมาใส่กระเป๋า'],['out','ลด / ย้ายเงินออกจากกระเป๋า']],v.direction):''}${cash?'<div class="notice">การแลกหรือถอนเงินของตัวเองเป็นการเพิ่มเงินสด ไม่ใช่รายได้ใหม่</div>':''}${settle?'<div class="notice">การคืนเงินปรับยอดระหว่างคุณกับเพื่อน ไม่เพิ่มรายจ่ายซ้ำ</div>':''}</section><section>${expense?`<fieldset class="splitpicker"><legend>แบ่งยอดนี้อย่างไร?</legend>${[['mine','ฉันคนเดียว'],['half','หารสอง'],['other','อีกคนทั้งหมด'],['custom','แบ่งเอง']].map(([k,l])=>`<label><input type="radio" name="split" value="${k}" ${v.split===k?'checked':''}><span>${l}</span></label>`).join('')}</fieldset><div id="walletCustom">${field('ส่วนของฉัน (สกุลเงินที่เลือก)','mine',v.mine,'text','inputmode="decimal"')}</div>${select('ใครจ่ายเงิน','payer',[['me',t.people[0]],['other',t.people[1]]],v.payer)}`:''}${!cash?select(v.kind==='income'?'รับเงินเข้าที่ไหน':'จ่าย / รับผ่าน','payment',[['cash','เงินสดตามสกุลที่เลือก'],['card','บัตร / บัญชี / บัตรเดินทาง']],v.payment):''}${field('วันที่จ่ายเงินจริง','date',v.date,'date')}${expense?select('ช่วงค่าใช้จ่าย','phase',[['auto','ตามวันที่จ่าย'],['before','ก่อนเดินทาง'],['during','ระหว่างทริป'],['after','หลังทริป']],v.phase):''}${textarea('บันทึกเพิ่มเติม (ไม่จำเป็น)','note',v.note)}<details><summary>เรทของรายการ · ¥1 ≈ ${thb(+v.rate||0)}</summary>${field('บาทต่อ 1 เยน','rate',v.rate,'text','inputmode="decimal"')}<p class="note">เก็บเรทนี้กับรายการเดิม แม้เรทของทริปจะเปลี่ยน</p></details></section></div><div class="wallet-savebar">${v.recordId?btn('ลบรายการ','walletdelete','danger',`data-source="${expense?'expense':'move'}" data-id="${esc(v.recordId)}"`):btn('ยกเลิก','walletcancel')}<button type="submit" class="btn primary wallet-save">${icon('check')} บันทึก${walletTypes[v.kind]}</button></div></form></div>`}
function walletFormValues(f){return Object.fromEntries(new FormData(f))}
function updateWalletPreview(f){const v=walletFormValues(f);Object.assign(walletDraft,v);const n=parseMoney(v.amount)||0,r=parseMoney(v.rate)||0,m=v.split==='half'?Math.round(n*50)/100:v.split==='other'?0:v.split==='custom'?parseMoney(v.mine)||0:n;const c=$('#walletCustom');if(c){c.hidden=v.split!=='custom';f.elements.namedItem('mine').disabled=v.split!=='custom'}$('#walletPreview').innerHTML=`<strong>≈ ${v.currency==='THB'?jpy(n/r):thb(n*r)}</strong><span>${v.kind==='expense'?`ส่วนฉัน ${v.currency==='THB'?thb(m):jpy(m)} · อีกคน ${v.currency==='THB'?thb(n-m):jpy(n-m)}`:v.kind==='income'?'รายรับส่วนตัว ไม่เกี่ยวกับยอดหาร':v.kind==='cash'?'ปรับเฉพาะยอดเงินสดในมือ':'ปรับยอดค้างคืนระหว่างกัน'}</span>`}
function walletTransaction(v,t){const native=parseMoney(v.amount),rate=parseMoney(v.rate),currency=v.currency==='THB'?'THB':'JPY',amount=currency==='THB'?native/rate:native;if(!Number.isFinite(amount)||native<.01||amount>999999999)throw Error('ใส่ยอดเงินมากกว่า 0 เช่น 1,200');if(!Number.isFinite(rate)||rate<=0||rate>=10)throw Error('กรุณาตรวจเรท เช่น 0.23 บาทต่อเยน');if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||Number.isNaN(Date.parse(v.date)))throw Error('กรุณาเลือกวันที่ให้ครบ');if(!walletTypes[v.kind])throw Error('ประเภทของรายการไม่ถูกต้อง');const record={id:v.recordId||uid(),title:(v.label||'').trim()||v.category||walletTypes[v.kind],amount,rate,currency,phase:v.phase||'auto',date:v.date,method:v.payment==='card'?'card':'cash',note:(v.note||'').trim(),createdAt:new Date().toISOString()};if(v.kind==='expense'){const split=v.split||'mine',mine=split==='mine'?amount:split==='other'?0:split==='half'?Math.round(native*50)/100/(currency==='THB'?rate:1):parseMoney(v.mine)/(currency==='THB'?rate:1);if(!Number.isFinite(mine)||mine<0||mine>amount)throw Error('ส่วนของฉันต้องไม่ติดลบหรือเกินยอดจ่ายรวม');if(v.recordId&&t.expenses.some(e=>e.original===v.recordId))throw Error('รายการนี้มีเงินคืนแล้ว กรุณาลบรายการเงินคืนก่อนแก้ต้นทาง');Object.assign(record,{mine,split,payer:v.payer==='other'?'other':'me',category:expenseCategories.includes(v.category)?v.category:'อื่น ๆ'});return {list:'expenses',record}}record.kind=v.kind;record.category=v.category||'';if(v.kind==='cash'){if(currency!=='JPY')throw Error('กระเป๋าเงินสดนี้ใช้เยน กรุณาเลือก JPY');record.method='cash'}if(['cash','settle'].includes(v.kind)&&v.direction==='out')record.amount=-amount;return {list:'moves',record}}
function persistWallet(next){const raw=JSON.stringify(next);try{localStorage.setItem('tabi-v1',raw);if(localStorage.getItem('tabi-v1')!==raw)throw Error('verify')}catch{throw Error('ยังบันทึกลงเครื่องไม่ได้ กรุณาเปิดใน Safari หรือ Chrome ปกติ และตรวจพื้นที่ว่าง ข้อมูลที่กรอกยังอยู่ในหน้านี้')}S=next}
function wireWalletForm(){const f=$('#walletform');if(!f)return;updateWalletPreview(f);f.addEventListener('input',()=>updateWalletPreview(f));f.addEventListener('change',()=>updateWalletPreview(f));f.addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();const error=$('#walletError'),submit=f.querySelector('[type="submit"]');error.hidden=true;submit.disabled=true;try{if(walletDraft.tripId!==T().id)throw Error('ทริปเปลี่ยนไป กรุณากลับไปเลือกทริปก่อนบันทึก');const v=walletFormValues(f),next=JSON.parse(JSON.stringify(S)),t=next.trips.find(x=>x.id===T().id),{list,record}=walletTransaction(v,t),index=t[list].findIndex(x=>x.id===record.id);if(index>=0){record.createdAt=t[list][index].createdAt||record.createdAt;t[list][index]=record}else t[list].push(record);persistWallet(next);walletMessage=`บันทึก${walletTypes[v.kind]} “${record.title}” ${nativeMoney(record)} แล้ว`;walletDraft=null;walletFilter='all';walletQuery='';moneyTab='ledger';render();scrollTo(0,0)}catch(e){error.textContent=e.message||'บันทึกไม่สำเร็จ กรุณาลองอีกครั้ง';error.hidden=false;error.scrollIntoView?.({block:'center',behavior:'smooth'});submit.disabled=false}})}
function walletRemove(source,id){const t=T();if(source==='expense'&&t.expenses.some(e=>e.original===id)){toast('ลบรายการคืนเงินที่เกี่ยวข้องก่อนลบต้นทาง');return}if(!confirm('ย้ายรายการนี้ไปถังขยะ? กู้คืนภายหลังได้'))return;try{const next=JSON.parse(JSON.stringify(S)),trip=next.trips.find(x=>x.id===t.id),list=source==='expense'?'expenses':'moves',record=trip[list].find(x=>x.id===id);if(!record)return;trip.walletTrash=trip.walletTrash||[];trip.walletTrash.push({source,record});trip[list]=trip[list].filter(x=>x.id!==id);persistWallet(next);$('#modal').close();walletDraft=null;moneyTab='ledger';walletMessage='ย้ายรายการไปถังขยะแล้ว กู้คืนได้จาก “รายการที่ลบ”';render()}catch(e){toast(e.message)}}
function walletTrash(){const t=T(),all=[...(t.walletTrash||[]),...t.trash.map(record=>({source:'legacy',record}))];modal('รายการที่ลบ',all.length?all.map(({source,record})=>`<div class="row"><div>${esc(record.title||walletTypes[record.kind]||'รายการ')}<p>${jpy(Math.abs(record.amount))}</p></div>${btn('กู้คืน','walletrestore','small',`data-source="${source}" data-id="${record.id}"`)}</div>`).join(''):'<p>ไม่มีรายการที่ลบ</p>')}
document.addEventListener('input',e=>{if(e.target.id==='walletSearch'){walletQuery=e.target.value;$('#walletRows').innerHTML=walletList()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.walletFilter){walletFilter=b.dataset.walletFilter;render();return}if(b.dataset.walletKind&&walletDraft&&!walletDraft.recordId){walletDraft.kind=b.dataset.walletKind;walletDraft.category=walletDraft.kind==='income'?'รายรับอื่น ๆ':'อาหาร';render();return}switch(b.dataset.action){case'walletincome':openWalletEntry('income');break;case'walletcancel':moneyTab='ledger';walletDraft=null;render();scrollTo(0,0);break;case'walletdismiss':walletMessage='';render();break;case'walletedit':{const t=T(),entry=(b.dataset.source==='expense'?t.expenses:t.moves).find(x=>x.id===b.dataset.id);if(entry){if(b.dataset.source==='expense')expenseModal(entry.id);else openWalletEntry(entry.kind,entry.id)}break}case'walletdelete':walletRemove(b.dataset.source,b.dataset.id);break;case'wallettrash':walletTrash();break;case'walletrestore':try{const next=JSON.parse(JSON.stringify(S)),t=next.trips.find(x=>x.id===T().id),legacy=b.dataset.source==='legacy',item=legacy?{source:'expense',record:t.trash.find(x=>x.id===b.dataset.id)}:(t.walletTrash||[]).find(x=>x.record.id===b.dataset.id);if(!item?.record)return;if(item.record.original&&!t.expenses.some(x=>x.id===item.record.original))throw Error('กู้คืนรายการต้นทางก่อนรายการเงินคืน');t[item.source==='expense'?'expenses':'moves'].push(item.record);if(legacy)t.trash=t.trash.filter(x=>x.id!==b.dataset.id);else t.walletTrash=t.walletTrash.filter(x=>x.record.id!==b.dataset.id);persistWallet(next);$('#modal').close();walletMessage='กู้คืนรายการแล้ว';render()}catch(err){toast(err.message)}break}});

let offlineState=null,offlineError='',offlineProgress='',offlineBusy=false,offlineDownloadQueued=false;
function offlinePanel(){const names={core:'หน้าแอป + ภาษา + ที่ควรไป',guide:'รูปและตัวอักษร',maps:'แผนที่รถไฟ',audio:'เสียงญี่ปุ่น',english:'เสียงอังกฤษ'},p=offlineState?.packs;return `<div class="offline-groups">${Object.entries(names).map(([k,n])=>`<div class="row"><span>${n}</span><strong>${p?`${p[k].ready}/${p[k].total} ${p[k].ready===p[k].total?'พร้อม':'ยังไม่ครบ'}`:'ยังไม่ได้ตรวจ'}</strong></div>`).join('')}</div><p class="note" role="status">${esc(offlineProgress||offlineError||'ตรวจจากไฟล์ที่เก็บในเบราว์เซอร์นี้')}</p><p class="note">${navigator.serviceWorker?.controller?'หน้าเว็บนี้อยู่ภายใต้ระบบออฟไลน์แล้ว':'ยังต้องรอระบบออฟไลน์ทำงาน แล้วปิด–เปิดหน้าใหม่'}</p><ol class="offline-steps"><li>เปิดลิงก์นี้ใน Safari / Chrome ขณะมีเน็ตและเข้าสู่ระบบให้เรียบร้อย</li><li>เพิ่มลงหน้าจอโฮม แล้วเปิดจากไอคอน ICHI-JAPAN ขณะออนไลน์อีกครั้ง</li><li>กดเตรียมใช้ออฟไลน์ในไอคอนนั้น รอทุกหมวดพร้อม</li><li>เปิดโหมดเครื่องบิน ปิดแล้วเปิดจากไอคอนเดิม ทดลองจดเงินและฟังเสียง</li></ol><p class="note">ครั้งแรกและการเข้าสู่ระบบต้องใช้เน็ต ลิงก์แปลภาษา เรทใหม่ และเส้นทางสดต้องใช้เน็ตด้วย การเพิ่มไอคอนอย่างเดียวไม่ได้ดาวน์โหลดข้อมูล</p>${btn('ฉันทดลองเปิดโหมดเครื่องบินสำเร็จแล้ว','offlineconfirmed','small soft')}<p class="note">${esc(S.offlineTest||'ยังไม่ได้ยืนยันผลทดลองบนเครื่องนี้')}<br>อย่าล้างข้อมูลเว็บก่อนส่งออกบัญชีและสำรอง</p>`}
function paintOffline(){if($('#offlinePanel'))$('#offlinePanel').innerHTML=offlinePanel()}
async function offlineRequest(download=false){if(offlineBusy){if(download)offlineDownloadQueued=true;return;}offlineBusy=true;offlineError='';offlineProgress=download?'กำลังเตรียมไฟล์…':'';paintOffline();try{if(!('serviceWorker'in navigator))throw Error('เบราว์เซอร์นี้ไม่รองรับ ให้เปิดใน Safari หรือ Chrome');const reg=navigator.onLine?await navigator.serviceWorker.register('./sw.js?v=109'):await navigator.serviceWorker.getRegistration();if(!reg)throw Error('ยังไม่ได้เตรียมออฟไลน์ ต้องเปิดออนไลน์ก่อน');if(reg.installing)await new Promise((resolve,reject)=>{const sw=reg.installing,timer=setTimeout(()=>reject(Error('เตรียมหน้าแอปไม่สำเร็จ ลองเปิดลิงก์ตรงและเข้าสู่ระบบใหม่')),30000);const done=()=>{if(sw.state==='activated'){clearTimeout(timer);resolve()}if(sw.state==='redundant'){clearTimeout(timer);reject(Error('ดาวน์โหลดหน้าแอปไม่ผ่าน ตรวจอินเทอร์เน็ตแล้วลองใหม่'))}};sw.addEventListener('statechange',done);done()});const active=reg.active;if(!active)throw Error('ระบบออฟไลน์ยังไม่พร้อม ลองเปิดหน้าใหม่ขณะออนไลน์');const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();reject(Error('ตรวจไม่สำเร็จ อาจยังเป็นรุ่นเก่า ปิดแล้วเปิดหน้าใหม่ขณะออนไลน์'))},download?180000:10000);channel.port1.onmessage=e=>{if(e.data.type==='PROGRESS'){offlineProgress=`ดาวน์โหลด ${e.data.done}/${e.data.total} ไฟล์`;paintOffline();return}clearTimeout(timer);channel.port1.close();if(!e.data.ok||e.data.version!==5)reject(Error(e.data.error||'ต้องเปิดเวอร์ชันใหม่ขณะออนไลน์ก่อน'));else resolve(e.data)};active.postMessage({type:download?'CACHE_APP':'STATUS'},[channel.port2])});offlineState=result;offlineProgress=download?(result.failed.length?'ยังไม่ครบ กดดาวน์โหลดซ้ำเพื่อเก็บเฉพาะไฟล์ที่ขาด':'ดาวน์โหลดครบแล้ว ต่อไปทดลองเปิดในโหมดเครื่องบิน'):'';if(download&&navigator.storage?.persist)await navigator.storage.persist().catch(()=>false)}catch(e){offlineError=e.message;offlineProgress=''}finally{offlineBusy=false;paintOffline();if(offlineDownloadQueued){offlineDownloadQueued=false;await offlineRequest(true)}}}
function backupSignature(){const c=JSON.parse(JSON.stringify(S));delete c.backupSignature;delete c.offlineTest;for(const t of c.trips)delete t.lastBackup;const str=JSON.stringify(c);let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function backupStatus(){return !S.backupSignature?'ยังไม่ได้สร้างไฟล์สำรอง':S.backupSignature===backupSignature()?'ไม่มีข้อมูลใหม่หลังสร้างไฟล์สำรองล่าสุด':'มีข้อมูลเปลี่ยนหลังสำรองครั้งล่าสุด ควรส่งออกอีกครั้ง'}
function nativeMoney(e){return e.currency==='THB'?thb(Math.abs(e.amount*e.rate)):jpy(Math.abs(e.amount))}
function expensePhase(e,t=T()){return ['before','during','after'].includes(e.phase)?e.phase:e.date<t.start?'before':e.date>t.end?'after':'during'}
function tripSummary(t=T()){const phases={before:0,during:0,after:0},categories={},days={};for(const e of t.expenses){const n=e.amount*e.rate;phases[expensePhase(e,t)]+=n;categories[e.category]=(categories[e.category]||0)+n;days[e.date]=(days[e.date]||0)+n}return {phases,categories,days,...totals(t)}}
function tripSummaryView(){const t=T(),z=tripSummary();return title('THE WHOLE JOURNEY','ค่าใช้จ่ายรวมทั้งทริป','รวมทุกรายการที่บันทึก แม้จ่ายก่อนวันเดินทาง',btn('กลับบัญชี','walletcancel','soft'))+`<section class="summary-hero"><div><span>รวมทุกคน · หลังหักเงินคืน</span><strong>${thb(z.tripCost)}</strong></div><div><span>ส่วนของฉัน</span><strong>${thb(z.cost)}</strong></div></section><div class="summary-phases">${Object.entries({before:'ก่อนเดินทาง',during:'ระหว่างทริป',after:'หลังทริป'}).map(([k,n])=>`<section class="card"><span>${n}</span><h2>${thb(z.phases[k])}</h2></section>`).join('')}</div><section class="card gap"><h2>เริ่มเก็บต้นทุนก่อนบิน</h2><p class="note">กรอกตามวันที่และสกุลเงินจริง ยังไม่บันทึกจนกดปุ่มบันทึก</p><div class="flex">${['ตั๋วเครื่องบิน','รถไป–กลับสนามบิน','ที่พัก','ประกัน','ซิม / อินเทอร์เน็ต'].map(c=>btn('+ '+c,'preexpense','small',`data-category="${c}"`)).join('')}</div></section><div class="grid two gap"><section class="card"><h2>รวมตามหมวด</h2>${Object.entries(z.categories).map(([c,n])=>`<div class="row"><span>${esc(c)}</span><strong>${thb(n)}</strong></div>`).join('')||'<p class="note">ยังไม่มีรายจ่าย</p>'}</section><section class="card"><h2>รวมแต่ละวัน</h2>${Object.entries(z.days).sort((a,b)=>a[0].localeCompare(b[0])).map(([d,n])=>`<div class="row"><span>${formatDate(d)}</span><strong>${thb(n)}</strong></div>`).join('')||'<p class="note">ยังไม่มีรายจ่าย</p>'}</section></div><section class="card gap"><h2>เก็บบัญชีหลังจบทริป</h2><p>ไฟล์รายงานเปิดอ่านได้โดยไม่ต้องเข้าเว็บนี้ มีทุกรายการ เรท และส่วนแบ่งของคุณ</p><div class="flex">${btn('ดาวน์โหลดรายงาน HTML','reporthtml','primary')}${btn('ดาวน์โหลด CSV สำหรับ Excel','reportcsv')}${btn('สำรองเพื่อนำกลับเข้าแอป','export')}</div><p class="note">HTML สำหรับอ่านและพิมพ์เป็น PDF จากเมนูเบราว์เซอร์ · CSV สำหรับตาราง · JSON สำหรับกู้คืนข้อมูล<br>${backupStatus()}</p></section>`}
function reportRows(){return walletEntries().slice().sort((a,b)=>a.date.localeCompare(b.date)).map(e=>[e.date,e.kind==='refund'?'รับคืนจากร้าน':walletTypes[e.kind],e.title,e.category||'',e.currency||'JPY',e.currency==='THB'?e.amount*e.rate:e.amount,e.rate,e.amount*e.rate,e.source==='expense'?e.mine*e.rate:'',e.source==='expense'?(T().people[payerIndex(e)]||'ไม่ระบุ'):'',e.method==='cash'?'เงินสด':'บัตร / บัญชี',e.source==='expense'?({before:'ก่อนเดินทาง',during:'ระหว่างทริป',after:'หลังทริป'}[expensePhase(e)]):'',e.note||''])}
const reportHeaders=['วันที่','ประเภท','รายการ','หมวด','สกุลเงิน','ยอดตามสกุลเงิน','บาทต่อเยน','ยอดเทียบบาท','ส่วนของฉันบาท','คนจ่าย','วิธีจ่าย','ช่วงทริป','หมายเหตุ'];
function reportHTML(){const t=T(),z=tripSummary();return `<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ICHI-JAPAN · ${esc(t.name)}</title><style>body{font-family:Tahoma,system-ui,sans-serif;color:#19383d;margin:35px;line-height:1.7}h1{font-size:26px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #dce6e8;text-align:left;padding:9px;vertical-align:top}th{background:#eef4f4}section{overflow:auto}.stats{padding:20px;background:#eef4f4;margin:20px 0}@media print{body{margin:12px}table{font-size:9px}thead{display:table-header-group}tr{break-inside:avoid}} </style><h1>ICHI-JAPAN</h1><h2>${esc(t.name)}</h2><p>${esc(t.start)} – ${esc(t.end)} · ${esc(t.people.join(' / '))}<br>สร้างรายงาน ${esc(today())}</p><div class="stats">รายจ่ายรวมทั้งทริป ${thb(z.tripCost)} · ส่วนของฉัน ${thb(z.cost)}<br>ก่อนเดินทาง ${thb(z.phases.before)} · ระหว่างทริป ${thb(z.phases.during)} · หลังทริป ${thb(z.phases.after)}<br>รายรับส่วนตัว ${thb(z.income)}<br>${z.debt>=0?'รอรับคืน':'ต้องคืนเพื่อน'} ${jpy(Math.abs(z.debt))} · ${z.debtTHB>=0?'รอรับคืน':'ต้องคืนเพื่อน'} ${thb(Math.abs(z.debtTHB))}</div><p>รายจ่ายหักเงินคืนแล้ว การเติมเงินสดและคืนเงินระหว่างกันไม่ถูกนับเป็นรายจ่ายซ้ำ รายการบาทใช้ยอดบาทจริง รายการเยนใช้เรทที่บันทึกไว้</p><section><table><thead><tr>${reportHeaders.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${reportRows().map(row=>`<tr>${row.map(v=>`<td>${esc(typeof v==='number'?Math.round(v*100000)/100000:v)}</td>`).join('')}</tr>`).join('')}</tbody></table></section><p>By ichitan · รายงานนี้ไม่มีไฟล์เอกสารแนบหรือรหัสผ่าน</p></html>`}
function reportCSV(){const quote=v=>{let s=String(typeof v==='number'?Math.round(v*100000)/100000:v);if(typeof v!=='number'&&/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};return '\ufeff'+[reportHeaders,...reportRows()].map(r=>r.map(quote).join(',')).join('\r\n')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;switch(b.dataset.action){case'pinphrase':{const i=+b.dataset.index,a=T().favorites||[],old=a.slice();T().favorites=a.includes(i)?a.filter(x=>x!==i):[...a,i];if(save()){if($('#phraseResults'))$('#phraseResults').innerHTML=phraseResults()}else T().favorites=old;break}case'favorites':phraseCategory='ปักหมุด';phraseQuery='';travelTab='phrases';go('travel');break;case'summary':moneyTab='summary';go('money');break;case'preexpense':openWalletEntry('expense','',{title:b.dataset.category,category:b.dataset.category,currency:'THB',phase:'before',split:'half'});break;case'reporthtml':downloadBlob(new Blob([reportHTML()],{type:'text/html;charset=utf-8'}),'ichi-japan-trip-'+today()+'.html');toast('สร้างรายงานแล้ว เลือกบันทึกไฟล์เก็บไว้');break;case'reportcsv':downloadBlob(new Blob([reportCSV()],{type:'text/csv;charset=utf-8'}),'ichi-japan-trip-'+today()+'.csv');toast('สร้าง CSV แล้ว เลือกบันทึกไฟล์เก็บไว้');break;case'offlinedetails':go('trip');$('#offlinePanel')?.scrollIntoView?.({block:'center'});break;case'offlineconfirmed':S.offlineTest='คุณยืนยันว่าเปิดในโหมดเครื่องบินได้ '+new Date().toLocaleString('th-TH');save();paintOffline();break;case'todayplan':go('plan');break;case'showmaps-home':travelTab='maps';go('travel');break;case'hotelcard':{const h=T().hotels.find(h=>h.id===b.dataset.id);if(h)modal('ที่พักของฉัน',`<div class="fullscreenjp"><p lang="ja">このホテルへ行きたいです。</p><h2>${esc(h.name)}</h2><p>${esc(h.address)}</p><p>${esc(h.phone)}</p></div>`);break}}});

function translatorPanel(){return `<details class="translator-composer"><summary>พิมพ์ข้อความใหม่เพื่อแปล</summary><p class="note">กดปุ่มแล้วเปิดข้อความนี้ใน Google Translate · ต้องมีเน็ต</p><label class="field">ข้อความ<textarea id="translateText" placeholder="พิมพ์ไทย อังกฤษ หรือให้คนญี่ปุ่นพิมพ์ตอบ…"></textarea></label>${select('ทิศทางภาษา','translatePair',[['th-ja','ไทย → ญี่ปุ่น'],['ja-th','ญี่ปุ่น → ไทย'],['th-en','ไทย → อังกฤษ'],['en-th','อังกฤษ → ไทย']],'th-ja')}${btn('เปิดข้อความใน Google Translate','translatecompose','primary')}</details>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.action==='translatecompose'){const value=$('#translateText').value.trim();if(!value){toast('พิมพ์ข้อความที่ต้องการแปลก่อน');return}const [from,to]=$('[name=translatePair]').value.split('-');window.open(translateURL(value,from,to),'_blank','noopener,noreferrer')}});

// ICHI-JAPAN 1.0.9: public trips, groups, travel tools and itinerary controls.
const APP_VERSION='1.0.9';
const personOptions=(t=T())=>t.people.map((n,i)=>[String(i),n]);
function payerIndex(e){return Number.isInteger(e.payerIndex)?e.payerIndex:e.payer==='other'?1:0}
function sharesOf(e,t=T()){if(Array.isArray(e.shares))return t.people.map((_,i)=>e.shares[i]||0);return t.people.map((_,i)=>i===0?e.mine:i===1?e.amount-e.mine:0)}
function allocateCents(total,weights){const sum=weights.reduce((a,b)=>a+b,0);if(!sum)return weights.map(()=>0);const raw=weights.map(w=>total*w/sum),out=raw.map(Math.floor);let rest=total-out.reduce((a,b)=>a+b,0);raw.map((v,i)=>({i,r:v-out[i]})).sort((a,b)=>b.r-a.r||a.i-b.i).slice(0,rest).forEach(x=>out[x.i]++);return out}
function refundShares(e,n,t){const scale=e.currency==='THB'?e.rate:1;return allocateCents(Math.round(n*scale*100),sharesOf(e,t).map(Math.abs)).map(x=>-x/100/scale)}
function groupBalances(t=T()){const out={JPY:t.people.map(()=>0),THB:t.people.map(()=>0)};for(const e of t.expenses){const c=e.currency==='THB'?'THB':'JPY',r=c==='THB'?e.rate:1;out[c][payerIndex(e)]+=e.amount*r;sharesOf(e,t).forEach((s,i)=>out[c][i]-=s*r)}for(const m of t.moves){if(m.kind!=='settle')continue;const c=m.currency==='THB'?'THB':'JPY',r=c==='THB'?m.rate:1,from=Number.isInteger(m.fromPerson)?m.fromPerson:m.amount<0?0:1,to=Number.isInteger(m.toPerson)?m.toPerson:m.amount<0?1:0;if(out[c][from]===undefined||out[c][to]===undefined)continue;out[c][from]+=Math.abs(m.amount)*r;out[c][to]-=Math.abs(m.amount)*r}return out}
const previousTotals=totals;
totals=function(t=T()){const z=previousTotals(t),b=groupBalances(t);for(const m of t.moves){if(m.kind==='settle'&&m.method==='cash'&&m.currency!=='THB'&&Number.isInteger(m.fromPerson)&&m.fromPerson!==0&&m.toPerson!==0)z.cash-=m.amount}z.debt=b.JPY[0]||0;z.debtTHB=b.THB[0]||0;return z};
function groupSummary(){const t=T(),b=groupBalances(t);return `<section class="card gap"><h2>ยอดค้างคืนรายคน</h2><p class="note">บวก = รอรับคืน · ลบ = ต้องจ่ายคืน แยกบาทและเยน ไม่แปลงหนี้ข้ามสกุล</p>${t.people.map((n,i)=>`<div class="row"><strong>${esc(n)}</strong><span>${jpy(Math.abs(b.JPY[i])<.005?0:b.JPY[i])} · ${thb(Math.abs(b.THB[i])<.005?0:b.THB[i])}</span></div>`).join('')}${t.people.length>1?btn('บันทึกคืนเงินระหว่างคนในทริป','settle'):''}<p class="note">ยอดสุทธิรวมการรับคืนจากร้านและรายการคืนเงินแล้ว</p></section>`}
const oldMoneyView=moneyView;moneyView=function(){const h=oldMoneyView();return moneyTab==='ledger'?h+groupSummary():h};
const oldSummary=tripSummaryView;tripSummaryView=function(){return oldSummary()+groupSummary()};
const oldReportRows=reportRows;reportHeaders.push('ส่วนแบ่งแต่ละคน (สกุลเงินจริง)','ผู้โอน → ผู้รับ');reportRows=function(){const rows=oldReportRows(),entries=walletEntries().slice().sort((a,b)=>a.date.localeCompare(b.date));return rows.map((r,i)=>{const e=entries[i],factor=e.currency==='THB'?e.rate:1;r.push(e.source==='expense'?sharesOf(e).map((n,j)=>T().people[j]+': '+(n*factor).toFixed(2)).join(' | '):'',e.kind==='settle'?`${T().people[e.fromPerson??(e.amount<0?0:1)]} → ${T().people[e.toPerson??(e.amount<0?1:0)]}`:'');return r})};
const oldOpenWallet=openWalletEntry;openWalletEntry=function(kind='expense',id='',prefill={}){oldOpenWallet(kind,id,prefill);const old=(kind==='expense'?T().expenses:T().moves).find(e=>e.id===id);walletDraft.payerIndex=old?payerIndex(old):0;walletDraft.groupMode=old?.groupMode||'equal';walletDraft.members=old?sharesOf(old).map((s,i)=>s!==0?i:-1).filter(i=>i>=0):prefill.split==='half'?T().people.map((_,i)=>i):[0];walletDraft.customShares=old?sharesOf(old).map(s=>String(s*(old.currency==='THB'?old.rate:1))):[];if(old&&!old.groupMode)walletDraft.groupMode='custom';walletDraft.fromPerson=old?.fromPerson??(old?.amount<0?0:1);walletDraft.toPerson=old?.toPerson??(old?.amount<0?1:0);if(kind==='settle'&&!old)walletDraft.amount='';render()};
const oldEntryView=walletEntryView;walletEntryView=function(){let h=oldEntryView(),v=walletDraft;if(!v)return h;if(v.kind==='expense'){const start=h.indexOf('<fieldset class="splitpicker">'),end=h.indexOf("</select></label>",start)+17;h=h.slice(0,start)+`<section class="group-split"><h2>หารกับใครบ้าง?</h2>${select('วิธีแบ่ง','groupMode',[['equal','เท่ากันเฉพาะคนที่เลือก'],['custom','ระบุยอดแต่ละคน']],v.groupMode||'equal')}<div class="member-shares">${T().people.map((n,i)=>`<div><label><input type="checkbox" name="member" value="${i}" ${(v.members||[0]).includes(i)?'checked':''}> ${esc(n)}</label><input aria-label="ส่วนแบ่งของ ${esc(n)}" name="share${i}" value="${esc(v.customShares?.[i]||'')}" inputmode="decimal" placeholder="ยอดส่วนแบ่ง"></div>`).join('')}</div><p class="note">เศษสตางค์ของการหารเท่ากันจัดตามลำดับรายชื่อ ยอดรวมตรงกับยอดจ่ายเสมอ</p>${select('ใครจ่ายเงิน','payerIndex',personOptions(),v.payerIndex||0)}</section>`+h.slice(end)}if(v.kind==='settle'){h=h.replace(/<label class="field">ทิศทาง[\s\S]*?<\/label>/,`<div class="grid two">${select('ผู้คืนเงิน','fromPerson',personOptions(),v.fromPerson??1)}${select('ผู้รับเงิน','toPerson',personOptions(),v.toPerson??0)}</div>`)}return h};
const oldFormValues=walletFormValues;walletFormValues=function(f){const v=oldFormValues(f);v.members=[...f.querySelectorAll('[name=member]:checked')].map(x=>+x.value);v.customShares=T().people.map((_,i)=>f.elements.namedItem('share'+i)?.value||'');return v};
function splitNative(v,t){const total=parseMoney(v.amount),cents=Math.round(total*100);if(!Number.isFinite(total)||total<=0)throw Error('กรอกยอดเงินมากกว่า 0');if(Math.abs(total*100-cents)>.00001)throw Error('ยอดเงินใช้ทศนิยมไม่เกิน 2 ตำแหน่ง');const members=v.members||[];if(!members.length||new Set(members).size!==members.length||members.some(i=>!Number.isInteger(i)||i<0||i>=t.people.length))throw Error('เลือกผู้ร่วมค่าใช้จ่ายอย่างน้อย 1 คน');let out=t.people.map(()=>0);if(v.groupMode==='custom'){for(const i of members){const n=parseMoney(v.customShares?.[i]);if(!Number.isFinite(n)||n<0)throw Error('กรอกส่วนแบ่งทุกคนที่เลือกเป็นยอดไม่ติดลบ');if(Math.abs(n*100-Math.round(n*100))>.00001)throw Error('ส่วนแบ่งใช้ทศนิยมไม่เกิน 2 ตำแหน่ง');out[i]=Math.round(n*100)}if(out.reduce((a,b)=>a+b,0)!==cents)throw Error('ยอดส่วนแบ่งรวมต้องเท่ากับยอดจ่าย')}else out=allocateCents(cents,t.people.map((_,i)=>members.includes(i)?1:0));return out.map(n=>n/100)}
updateWalletPreview=function(f){const v=walletFormValues(f);Object.assign(walletDraft,v);f.querySelectorAll('[name^=share]').forEach(el=>{el.hidden=v.groupMode!=='custom';el.disabled=v.groupMode!=='custom'||!v.members.includes(+el.name.slice(5))});const n=parseMoney(v.amount)||0,r=parseMoney(v.rate)||0;let preview='';try{preview=v.kind==='expense'?splitNative(v,T()).map((a,i)=>`${esc(T().people[i])} ${v.currency==='THB'?thb(a):jpy(a)}`).join(' · '):v.kind==='settle'?'คืนเงินระหว่างคนที่เลือก ไม่เพิ่มรายจ่าย':'บันทึกยอดส่วนตัว'}catch(e){preview=esc(e.message)}$('#walletPreview').innerHTML=`<strong>≈ ${v.currency==='THB'?(r>0?jpy(n/r):'ตั้งเรทก่อน'):thb(n*r)}</strong><span>${preview}</span>`};
const oldTransaction=walletTransaction;walletTransaction=function(v,t){if(v.kind==='expense'){const native=splitNative(v,t),i=Number(v.payerIndex);if(!Number.isInteger(i)||i<0||i>=t.people.length)throw Error('เลือกผู้จ่ายเงิน');const out=oldTransaction({...v,split:'custom',mine:String(native[0]),payer:i===0?'me':'other'},t);out.record.shares=native.map(x=>x/(v.currency==='THB'?out.record.rate:1));out.record.mine=out.record.shares[0];out.record.payerIndex=i;out.record.groupMode=v.groupMode||'equal';out.record.members=v.members;return out}const out=oldTransaction(v,t);if(v.kind==='settle'){const a=Number(v.fromPerson),b=Number(v.toPerson);if(!Number.isInteger(a)||!Number.isInteger(b)||a===b||a<0||b<0||a>=t.people.length||b>=t.people.length)throw Error('เลือกผู้คืนและผู้รับเงินเป็นคนละคน');Object.assign(out.record,{fromPerson:a,toPerson:b,amount:Math.abs(out.record.amount)*(a===0?-1:1)});}return out};
let editingTripPeople=[];
const oldTripModal=tripModal;tripModal=function(isnew=false){oldTripModal(isnew);editingTripPeople=[...(isnew?['ฉัน']:T().people)];const f=$('#tripform');f.elements.person0.closest('label').remove();f.elements.person1.closest('label').remove();const box=document.createElement('section');box.innerHTML=`<h3>คนในทริป</h3><div class="flex">${[1,2,3,4].map(n=>btn(n===1?'เที่ยวคนเดียว':n+' คน','peoplecount','small',`data-count="${n}"`)).join('')}${btn('+ เพิ่มคน','peopleadd','small')}</div><div id="peopleFields"></div><p class="note">คนแรกคือเจ้าของบัญชีนี้ เพิ่มได้ถึง 20 คน รายชื่อที่มีรายการเงินแล้วเปลี่ยนชื่อได้ แต่ไม่ควรสลับคน</p>`;f.querySelector('.dialogactions').before(box);paintPeopleFields()};
function paintPeopleFields(){const box=$('#peopleFields');if(box)box.innerHTML=editingTripPeople.map((n,i)=>field(i===0?'ชื่อของฉัน':'ผู้ร่วมทริป '+(i+1),'person'+i,n,'text','required maxlength="40"')).join('')}
function capturePeople(){editingTripPeople=editingTripPeople.map((n,i)=>$('#tripform')?.elements.namedItem('person'+i)?.value??n)}
function commitState(mutator){const next=JSON.parse(JSON.stringify(S));mutator(next,next.trips.find(t=>t.id===T().id));persistWallet(next)}
document.addEventListener('submit',e=>{const f=e.target;if(f.getAttribute('id')!=='tripform')return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f));try{capturePeople();const names=editingTripPeople.map(n=>n.trim());if(names.some(n=>!n)||new Set(names).size!==names.length)throw Error('กรอกชื่อไม่ซ้ำกันให้ครบทุกคน');if(!v.start||!v.end||v.end<v.start||(new Date(v.end)-new Date(v.start))/864e5>89)throw Error('เลือกวันเดินทางให้ถูกต้อง ไม่เกิน 90 วัน');if(!v.name.trim())throw Error('กรอกชื่อทริป');const before=T();if(v.isnew!=='1'&&names.length<before.people.length&&(before.expenses.length||before.moves.length||before.trash.length||(before.walletTrash||[]).length))throw Error('ทริปมีประวัติการเงินแล้ว จึงลดจำนวนคนไม่ได้ สร้างทริปใหม่แทน');for(const k of ['budget','daily','cash'])if(!Number.isFinite(Number(v[k]))||Number(v[k])<0)throw Error('งบและเงินสดต้องไม่ติดลบ');commitState((state,t)=>{const dest=v.isnew==='1'?initialTrip():t;Object.assign(dest,{setupComplete:true,name:v.name.trim(),city:v.city,start:v.start,end:v.end,people:names,airport:v.airport,budget:+v.budget,daily:+v.daily,cash:+v.cash,meeting:v.meeting,contact:v.contact,backup:v.backup});if(v.isnew==='1'){state.trips.push(dest);state.current=dest.id}});day='';guideAirport='';$('#modal').close();render();toast('บันทึกทริปแล้ว')}catch(err){toast(err.message)}},true);
const oldValidate=validateImport;validateImport=function(d){oldValidate(d);for(const t of d.state.trips){for(const e of [...t.expenses,...t.trash,...(t.walletTrash||[]).filter(x=>x.source==='expense').map(x=>x.record)]){if(e.shares){if(!Array.isArray(e.shares)||e.shares.length>t.people.length||e.shares.some(n=>!Number.isFinite(n))||Math.abs(e.shares.reduce((a,b)=>a+b,0)-e.amount)>.0001||Math.abs((e.shares[0]||0)-e.mine)>.0001||!Number.isInteger(e.payerIndex)||e.payerIndex<0||e.payerIndex>=t.people.length)throw Error('ส่วนแบ่งหรือผู้จ่ายในไฟล์สำรองไม่ถูกต้อง')}}for(const m of t.moves){if(m.fromPerson!==undefined&&(!Number.isInteger(m.fromPerson)||!Number.isInteger(m.toPerson)||m.fromPerson<0||m.toPerson<0||m.fromPerson>=t.people.length||m.toPerson>=t.people.length||m.fromPerson===m.toPerson))throw Error('ข้อมูลการคืนเงินไม่ถูกต้อง')}}return d};
const sourceLinks={nrt:'https://www.narita-airport.jp/en/flight/',hnd:'https://tokyo-haneda.com/en/flight/',kix:'https://www.kansai-airport.or.jp/en/flight/',jre:'https://traininfo.jreast.co.jp/train_info/e/kanto.aspx',jrw:'https://global.trafficinfo.westjr.co.jp/en/kinki',metro:'https://www.tokyometro.jp/lang_en/index.html',osaka:'https://subway.osakametro.co.jp/en/',jma:'https://www.jma.go.jp/jma/kokusai/multi.html',embassy:'https://site.thaiembassy.jp/',consulate:'https://osaka.thaiembassy.org/'};
const nowTime=()=>new Date().toISOString();
function when(iso){return iso?new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Tokyo',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(iso))+' ญี่ปุ่น':'ยังไม่มีข้อมูล'}
function liveStore(){return S.liveData||{}}
let liveBusy=false,liveErrors={},lastLiveAttempt=0;
function weatherName(code){return code===0?'ฟ้าโปร่ง':code<=3?'มีเมฆ':code<=48?'หมอก':code<=67?'ฝน':code<=77?'หิมะ':code<=82?'ฝนเป็นช่วง':code<=86?'หิมะเป็นช่วง':'พายุฝนฟ้าคะนอง'}
async function getJSON(url){const c=new AbortController(),timer=setTimeout(()=>c.abort(),15000);try{const r=await fetch(url,{signal:c.signal,cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function refreshLive(){if(liveBusy)return;if(!navigator.onLine){toast('ออฟไลน์ แสดงข้อมูลที่บันทึกไว้พร้อมเวลาเดิม');return}lastLiveAttempt=Date.now();liveBusy=true;liveErrors={};if(page==='now')render();const tasks=[...Object.entries({tokyo:[35.6762,139.6503],osaka:[34.6937,135.5023]}).map(([key,[lat,lon]])=>({key,run:async()=>{const d=await getJSON(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,apparent_temperature,precipitation,weather_code&timezone=Asia%2FTokyo`);if(!Number.isFinite(d.current?.temperature_2m))throw Error('รูปแบบอากาศไม่ถูกต้อง');return {fetched:nowTime(),observed:d.current.time,temperature:d.current.temperature_2m,feels:d.current.apparent_temperature,rain:d.current.precipitation,code:d.current.weather_code}}})),{key:'quakes',run:async()=>{const from=new Date(Date.now()-864e5).toISOString();const d=await getJSON(`https://earthquake.usgs.gov/fdsnws/event/1/query?format=geojson&starttime=${encodeURIComponent(from)}&minlatitude=24&maxlatitude=46&minlongitude=122&maxlongitude=150&minmagnitude=4&orderby=time&limit=20`);if(!Array.isArray(d.features))throw Error('รูปแบบข้อมูลแผ่นดินไหวไม่ถูกต้อง');return {fetched:nowTime(),items:d.features.map(f=>({id:f.id,mag:f.properties.mag,place:f.properties.place,time:f.properties.time}))}}}];const results=await Promise.allSettled(tasks.map(async t=>({key:t.key,data:await t.run()})));let success=0;for(let i=0;i<results.length;i++){const r=results[i];if(r.status==='fulfilled'){try{commitState(state=>{state.liveData=state.liveData||{};state.liveData[r.value.key]=r.value.data});success++}catch(e){liveErrors[tasks[i].key]=e.message}}else liveErrors[tasks[i].key]='อัปเดตไม่สำเร็จ คงข้อมูลเดิมไว้'}liveBusy=false;if(page==='now')render();toast(`อัปเดต ${success}/${tasks.length} แหล่งข้อมูลแล้ว`)}
function liveNote(x,key){return `<p class="note">${navigator.onLine?'ข้อมูลที่บันทึกล่าสุด':'ออฟไลน์ · ข้อมูลที่บันทึกไว้'} ${when(x?.fetched)}${x?.fetched&&Date.now()-Date.parse(x.fetched)>3600000?' · เกิน 1 ชั่วโมงแล้ว':''}${liveErrors[key]?'<br>'+esc(liveErrors[key]):''}</p>`}
function manualStatus(k,label,urls){const x=T().liveNotes?.[k];return `<section class="card"><h2>${label}</h2><span class="pill">ตรวจจากแหล่งทางการ · ไม่ดึงอัตโนมัติ</span><p>${esc(x?.text||'ยังไม่ได้บันทึกผลตรวจ ไม่ได้หมายความว่าบริการปกติ')}</p><p class="note">${x?'คุณบันทึกเมื่อ '+when(x.checked):'ไม่มีผลตรวจล่าสุด'}</p><div class="flex">${urls.map(([n,u])=>link(n,u)).join('')}${btn('บันทึกผลที่ตรวจแล้ว','manualstatus','small',`data-key="${k}"`)}</div></section>`}
function nowView(){const d=liveStore(),t=T();return title('CONNECTED WHEN YOU NEED IT','ตอนนี้','ข้อมูลทุกส่วนมีเวลาและที่มา · เวลาในหน้านี้เป็นเวลาญี่ปุ่น',btn(liveBusy?'กำลังอัปเดต…':'อัปเดตอากาศ / แผ่นดินไหว','liverefresh','primary',liveBusy?'disabled':''))+`<div class="grid two">${['tokyo','osaka'].map(k=>{const w=d[k];return `<section class="card"><span class="eyebrow">${k.toUpperCase()}</span><h2>${w?w.temperature+'°C':'ยังไม่มีข้อมูลอากาศ'}</h2>${w?`<p>${weatherName(w.code)} · รู้สึกเหมือน ${w.feels}°C · ฝน ${w.rain} mm</p><small>เวลาแบบจำลอง ${esc(w.observed)}</small>`:''}${liveNote(w,k)}<a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo · ข้อมูลจากแบบจำลอง</a></section>`}).join('')}<section class="card"><h2>เรท JPY / THB</h2><strong>¥1 ≈ ${thb(t.rate)}</strong><p>${esc(t.rateSource)} · วันที่ข้อมูล ${esc(t.rateDate||'ยังไม่ได้อัปเดต')}</p>${btn('อัปเดตเรทอ้างอิงรายวัน','ratefetch')}<p class="note">เป็นเรทอ้างอิง ไม่ใช่เรทแลกเงินหน้าร้านหรือราคาซื้อขายทันที</p></section><section class="card"><h2>เที่ยวบินของฉัน</h2><p>${esc(t.flight?.number||'ยังไม่ระบุเที่ยวบิน')} · ${esc(t.flight?.date||'')}</p>${btn('กรอกเที่ยวบิน','flightedit')}<p class="note">ยังไม่ได้เชื่อม API สถานะเที่ยวบิน / Delay ใช้หน้าเที่ยวบินทางการแล้วบันทึกผลด้านล่าง</p></section>${manualStatus('flight','เที่ยวบิน / Delay',[['สนามบินที่เลือก',sourceLinks[t.airport||'nrt']]])}${manualStatus('rail','รถไฟล่าช้า / หยุดเดินรถ',[['JR East',sourceLinks.jre],['JR West',sourceLinks.jrw],['Tokyo Metro',sourceLinks.metro],['Osaka Metro',sourceLinks.osaka]])}<section class="card"><h2>แผ่นดินไหวที่รายงานแล้ว</h2><span class="pill">USGS · M4+ · 24 ชั่วโมง · ญี่ปุ่นและบริเวณใกล้เคียง</span>${liveNote(d.quakes,'quakes')}${d.quakes?(d.quakes.items.length?d.quakes.items.map(q=>`<div class="row"><strong>M${esc(q.mag)}</strong><div>${esc(q.place)}<p class="note">${when(q.time)}</p></div></div>`).join(''):'<p>ไม่พบเหตุที่เข้าเกณฑ์ในชุดข้อมูลที่ดาวน์โหลด ไม่ได้ยืนยันว่าปลอดภัยหรือไม่มีเหตุอื่น</p>'):'<p>ยังไม่มีข้อมูล กดอัปเดตเมื่อออนไลน์</p>'}<p class="note">เป็นเหตุที่เกิดแล้ว ไม่ใช่ระบบเตือนก่อนแผ่นดินไหว และไม่มีแจ้งเตือนเมื่อปิดแอป</p>${link('ประกาศแผ่นดินไหว / สึนามิ JMA',sourceLinks.jma)}</section>${manualStatus('storm','พายุ / ประกาศเตือนภัย',[['เปิดประกาศล่าสุด JMA',sourceLinks.jma]])}</div><p class="note">เก็บเฉพาะข้อมูลที่ดึงสำเร็จและผลตรวจที่คุณพิมพ์ไว้ ลิงก์เว็บภายนอกต้องมีเน็ต สถานะเก่าไม่ใช่สถานการณ์สด</p>`}
function tonight(){const t=T(),d=today();return t.hotels.find(h=>h.from<=d&&h.to>d)}
const safeTel=x=>String(x||'').replace(/[^+\d]/g,'');
function phoneLink(label,n){return safeTel(n)?`<a class="btn" href="tel:${safeTel(n)}">${esc(label)} · ${esc(n)}</a>`:'<p class="note">ยังไม่ได้ระบุ '+esc(label)+'</p>'}
function hotelCard(h){return h?`<h3>${esc(h.name)}</h3><p class="jp">${esc(h.address)}</p>${phoneLink('โทรที่พัก',h.phone)}${link('นำทางออนไลน์','https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(h.address||h.name))}`:'<p>ยังไม่มีที่พักสำหรับคืนนี้</p>'+btn('เพิ่มที่พัก','hotel')}
function emergencyView(){const t=T(),x=t.emergency||{};modal('SOS · ฉุกเฉิน',`<div class="sos-panel"><p>อยู่ในญี่ปุ่นและมีเหตุฉุกเฉิน โทรจากเครือข่ายที่โทรออกได้ eSIM แบบข้อมูลอย่างเดียวอาจโทรไม่ได้ ให้ขอคนใกล้ตัวช่วยโทร</p><div class="grid two">${phoneLink('ตำรวจ','110')}${phoneLink('รถพยาบาล / ดับเพลิง','119')}</div><section class="card gap"><h2>ที่พักคืนนี้</h2>${hotelCard(tonight())}</section><section class="card gap"><h2>คนที่ช่วยคุณได้</h2>${phoneLink(x.contactName||'ผู้ติดต่อฉุกเฉิน',x.contactPhone)}${phoneLink(x.insuranceName||'ประกันเดินทาง',x.insurancePhone)}<p>เลขกรมธรรม์: ${esc(x.policy||'ยังไม่ระบุ')}</p>${btn('ตั้งค่าผู้ติดต่อ / ประกัน','emergencyedit')}</section><section class="card gap"><h2>หน่วยงานช่วยเหลือ</h2>${link('สถานทูตไทย ณ กรุงโตเกียว',sourceLinks.embassy)}${link('สถานกงสุลไทย ณ โอซาก้า',sourceLinks.consulate)}${phoneLink('กงสุลโอซาก้า · คนไทยกรณีฉุกเฉิน','090-1895-0987')}${phoneLink('JNTO Visitor Hotline','050-3816-2787')}${phoneLink('กรมการกงสุลไทย · 24 ชั่วโมง','+6625728442')}<p class="note">JNTO: อังกฤษ จีน เกาหลี ญี่ปุ่น ตลอด 24 ชั่วโมง · <a href="https://www.japan.travel/en/plan/hotline/" target="_blank" rel="noopener">ข้อมูลทางการ</a> ตรวจ 30 ก.ย. 2026<br><a href="https://osaka.thaiembassy.org/th/publicservice/for-thaitourist" target="_blank" rel="noopener">เบอร์กงสุลโอซาก้า</a> · <a href="https://consular.mfa.go.th/th/content/update-hotline" target="_blank" rel="noopener">กรมการกงสุล</a><br>ลิงก์สถานทูตต้องใช้เน็ต ควรบันทึกเบอร์ที่ตรวจสอบแล้วในผู้ติดต่อก่อนเดินทาง</p></section><h2>แสดงให้คนใกล้ตัวอ่าน</h2><div class="flex">${['ฉันหลงทาง','ฉันไม่สบาย','พาสปอร์ตหาย'].map((x,i)=>btn(x,'sosphrase','soft',`data-index="${i}"`)).join('')}</div></div>`)}
const sosPhrases=[['ฉันหลงทาง','道に迷いました。助けてください。','มิจิ นิ มาโยอิมาชิตะ ทาสึเคเตะ คุดาไซ'],['ฉันไม่สบาย','気分が悪いです。助けてください。','คิบุน งะ วารุอิ เดส ทาสึเคเตะ คุดาไซ'],['พาสปอร์ตหาย','パスポートをなくしました。','พาสุโปโตะ โอะ นาคุชิมาชิตะ']];
function placesView(){const p=T().places||[];return `<section class="card gap"><div class="cardhead"><h2>Places · อยากไปที่ไหน</h2>${btn('+ เพิ่มสถานที่','placeedit','primary')}</div><p class="note">บันทึกแยกจากแผนรายวัน ปักดาวไว้ก่อน แล้วค่อยเลือกวันไป</p>${p.length?p.slice().sort((a,b)=>Number(b.star)-Number(a.star)).map(x=>`<article class="place-row"><div><h3>${esc(x.name)}</h3><p>${esc(x.city||'')} · ${x.visited?'ไปแล้ว':'ยังไม่ได้ไป'}</p><p>${esc(x.note||'')}</p></div><div class="flex">${btn(x.star?'★':'☆','placestar','small',`data-id="${x.id}" aria-label="ปักดาว ${esc(x.name)}"`)}${btn(x.visited?'ไปแล้ว ✓':'เช็กว่าไปแล้ว','placevisited','small',`data-id="${x.id}"`)}${btn('ใส่แผน','placeplan','small',`data-id="${x.id}"`)}${btn('แก้ไข','placeedit','small',`data-id="${x.id}"`)}</div></article>`).join(''):'<p>ยังไม่มีสถานที่ในรายการของคุณ</p>'}<details><summary>ตัวอย่างชื่อสถานที่ — กดเพื่อเพิ่มเอง</summary><div class="flex gap">${['Tokyo Disneyland','Shibuya Sky','teamLab','Don Quijote'].map(n=>btn('+ '+n,'placesample','small',`data-name="${n}"`)).join('')}</div></details></section>`}
const oldPlanView=planView;planView=function(){return oldPlanView()+placesView()};
function editPlace(id='',sample=''){const x=(T().places||[]).find(p=>p.id===id)||{};formModal('สถานที่ที่อยากไป','placeform',`<input type="hidden" name="id" value="${esc(id)}">${field('ชื่อสถานที่','name',x.name||sample,'text','required maxlength="120"')}${field('เมือง / ย่าน','city',x.city||'')}${textarea('ที่อยู่ / หมายเหตุ','note',x.note||'')}${id?btn('ลบสถานที่','placedelete','danger',`data-id="${id}"`):''}`)}
const railLessons=[
['Tokyo JR / Yamanote','ใช้แผนที่ JR แยกจาก Subway เลือกชื่อสถานีภาษาอังกฤษและป้ายสายสีเขียว Yamanote ตรวจสถานีถัดไปบนจอเพื่อเลือกทิศทางของวงแหวน เช่น Shinjuku → Shibuya ต้องตรวจว่าขบวนผ่าน Yoyogi / Harajuku ก่อน อย่าเลือกจากสีอย่างเดียว','https://www.jreast.co.jp/en/multi/'],
['Kyoto จาก Osaka','เลือกสถานีปลายทางในเกียวโตก่อน JR เหมาะกับ Kyoto Station ส่วนปลายทางย่านอื่นอาจต้องใช้ผู้ให้บริการอื่น ตรวจป้ายประเภทขบวนและจุดจอดก่อนขึ้น แล้วต่อรถในเมืองตามจุดหมาย','https://www.westjr.co.jp/global/en/'],
['Disney Resort','ปลายทาง JR Maihama (舞浜) บน Keiyo / Musashino Line จาก Tokyo Station ตามป้าย Keiyo Line และเผื่อเวลาเดินเปลี่ยนชานชาลา จาก Maihama ไป DisneySea ต่อ Disney Resort Line ได้ ตรวจจุดหมาย Disneyland หรือ DisneySea ให้ถูก','https://www.tokyodisneyresort.jp/en/tdr/access/railway'],
['Fuji / Kawaguchiko','ตรวจปลายทาง Kawaguchiko (河口湖) หากเริ่ม Shinjuku มี Limited Express FUJI EXCURSION หรือเดินทางไปเปลี่ยนที่ Otsuki (大月) เข้าสาย Fujikyu ต้องตรวจตั๋วที่นั่งและช่วงเส้นทางที่ตั๋วครอบคลุมก่อนขึ้น ไม่ใช่ทุกขบวนไปถึง Kawaguchiko','https://www.jreast.co.jp/en/multi/traininformation/azusa_kaiji/index.html'],
['Shinkansen','เส้น Tokyo / Shinagawa → Kyoto → Shin-Osaka ให้ขึ้นที่ประตู Shinkansen ตามตั๋ว ตรวจชื่อขบวน วัน เวลา รถคันที่และที่นั่ง Osaka Station กับ Shin-Osaka เป็นคนละสถานี เก็บตั๋วไว้ใช้ตอนออก','https://global.jr-central.co.jp/en/onlinebooking/contents/kyoto/'],
['IC Card · Suica / PASMO / ICOCA','ใช้แตะเข้าและออกด้วยบัตรใบเดียวกันในพื้นที่ที่รองรับ ตรวจสัญลักษณ์ IC และยอดคงเหลือ บัตรไม่ครอบคลุมทุกเส้นทาง และไม่ใช่ตั๋ว Limited Express / Shinkansen โดยอัตโนมัติ ตรวจการจองหรือการผูกบัตรของบริการนั้นก่อนเดินทาง','https://www.westjr.co.jp/global/en/howto/icoca/area/']];
function railMore(){modal('คู่มือรถไฟเพิ่มเติม',`<p>แนวทางเลือกเส้นทาง ไม่ใช่ตารางรถหรือค่าโดยสารสด ตรวจป้ายและประกาศวันเดินทาง</p>${railLessons.map(([title,body,url])=>`<details class="qa-card"><summary>${title}</summary><div class="qa-body"><p>${body}</p>${link('ดูข้อมูลผู้ให้บริการ',url)}${btn('เก็บเป็นแผน','raillesson','small',`data-index="${railLessons.findIndex(x=>x[0]===title)}"`)}</div></details>`).join('')}<p class="note">ทบทวนแหล่งข้อมูล 30 ก.ย. 2026</p>`)}
const oldTravelView=travelView;travelView=function(){return `<section class="rail-shortcut"><div><span class="eyebrow">QUICK RAIL GUIDE</span><b>JR · Disney · Fuji · Shinkansen</b><small>รวมทางไปจุดหลักแบบอ่านง่าย</small></div>${btn('เปิดคู่มือรถไฟ','railmore','soft')}</section>`+oldTravelView()};
const oldHomeView=homeView;homeView=function(){const base=oldHomeView();if(T().setupComplete===false)return base;const h=tonight(),t=T(),d=liveStore()[t.city==='osaka'?'osaka':'tokyo'];return `<section class="today-tools card"><span class="eyebrow">หยิบใช้ตอนนี้</span><div class="flex">${btn('กลับที่พักคืนนี้','tonighthotel','primary')}${btn('ข้อมูลตอนนี้','gotonow')}${btn('จดรายจ่าย','expense')}${btn('ประโยคปักหมุด','favorites')}</div><p class="note">${h?'คืนนี้: '+esc(h.name):'คืนนี้ยังไม่มีที่พักที่บันทึกไว้'}${d?' · '+d.temperature+'°C · อากาศบันทึกเมื่อ '+when(d.fetched):''}</p></section>`+base};
let updateInfo='',updateWaiting=false,updateApplying=false;
function versionPanel(){return `<section class="card gap"><div class="cardhead"><h2>ICHI-JAPAN v${APP_VERSION}</h2><span class="pill">By ichitan</span></div><p id="updateInfo">${esc(updateInfo||'ตรวจเวอร์ชันใหม่ขณะออนไลน์ได้ ข้อมูลทริปจะยังอยู่')}</p><div class="flex">${btn('ตรวจอัปเดต','checkupdate')}${updateWaiting?btn('ติดตั้งเวอร์ชันใหม่ / เปิดหน้าใหม่','applyupdate','primary'):''}</div><p class="note">บันทึกฟอร์มที่กำลังกรอกก่อนอัปเดต จากนั้นเตรียมออฟไลน์อีกครั้งเพื่อยืนยันไฟล์ครบ</p></section>`}
async function checkUpdate(){if(!navigator.onLine){updateInfo='ออฟไลน์ · เวอร์ชันที่เปิดอยู่ '+APP_VERSION;render();return}try{const meta=await getJSON('./version.json?check='+Date.now());if(!/^\d+\.\d+\.\d+$/.test(meta.version))throw Error('version');const reg=await navigator.serviceWorker?.getRegistration();if(reg)await reg.update();updateWaiting=!!reg?.waiting;updateInfo=meta.version===APP_VERSION?'เป็นเวอร์ชันล่าสุด '+APP_VERSION:'พบเวอร์ชัน '+meta.version+' กำลังเตรียมไฟล์อัปเดต';if(reg?.installing){const sw=reg.installing;sw.addEventListener('statechange',()=>{if(sw.state==='installed'){updateWaiting=!!reg.waiting;updateInfo=updateWaiting?'มีเวอร์ชันใหม่พร้อมติดตั้ง':'ไฟล์พร้อมแล้ว';if(page==='trip')render()}})}if(meta.version!==APP_VERSION&&!updateWaiting&&reg?.active&&!reg.installing){updateWaiting=true;updateInfo+=' · เปิดหน้าใหม่เพื่อโหลด'}render()}catch{updateInfo='ตรวจอัปเดตไม่สำเร็จ ใช้เวอร์ชันนี้ต่อได้';render()}}
async function applyUpdate(){if(walletDraft){toast('บันทึกหรือยกเลิกรายการที่กำลังกรอกก่อนอัปเดต');return}if(!save())return;const reg=await navigator.serviceWorker?.getRegistration();if(reg?.waiting){updateApplying=true;reg.waiting.postMessage({type:'SKIP_WAITING'})}else location.reload()}
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(updateApplying)location.reload()});
const oldTripView=tripView;tripView=function(){return versionPanel()+`<section class="card gap"><h2>ข้อมูลช่วยเหลือฉุกเฉิน</h2><p>เตรียมเบอร์ผู้ติดต่อ ประกัน และเลขกรมธรรม์ไว้ใช้ตอนไม่มีเน็ต</p>${btn('ตั้งค่าข้อมูลฉุกเฉิน','emergencyedit')}</section>`+oldTripView()};
const oldRender=render;render=function(){oldRender();const top=$('#topbar .flex');if(top)top.insertAdjacentHTML('afterbegin',`<button type="button" class="sos-button" data-action="sos">SOS <span>ฉุกเฉิน</span></button>`);const foot=document.querySelector('.signature');if(foot)foot.textContent='By ichitan · v'+APP_VERSION;if(page==='now'&&navigator.onLine&&!liveBusy&&Date.now()-lastLiveAttempt>900000)setTimeout(()=>{if(page==='now'&&!liveBusy&&Date.now()-lastLiveAttempt>900000)refreshLive()},0)};
const extensionActions=new Set(['peoplecount','peopleadd','liverefresh','gotonow','sos','emergencyedit','sosphrase','tonighthotel','flightedit','manualstatus','placeedit','placesample','placestar','placevisited','placedelete','placeplan','railmore','raillesson','checkupdate','applyupdate']);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!extensionActions.has(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.action,id=b.dataset.id;try{switch(a){case'peoplecount':case'peopleadd':capturePeople();{const n=a==='peopleadd'?editingTripPeople.length+1:+b.dataset.count;if(n>20){toast('รองรับสูงสุด 20 คน');break}editingTripPeople=Array.from({length:n},(_,i)=>editingTripPeople[i]||'');paintPeopleFields()}break;case'liverefresh':await refreshLive();break;case'gotonow':go('now');break;case'sos':emergencyView();break;case'tonighthotel':modal('กลับที่พักคืนนี้',hotelCard(tonight()));break;case'emergencyedit':{const x=T().emergency||{};$('#modal').close();formModal('ข้อมูลฉุกเฉินของฉัน','emergencyform',field('ชื่อผู้ติดต่อ','contactName',x.contactName||'')+field('เบอร์ผู้ติดต่อพร้อมรหัสประเทศ','contactPhone',x.contactPhone||'','tel')+field('บริษัทประกัน','insuranceName',x.insuranceName||'')+field('เบอร์ช่วยเหลือของประกัน','insurancePhone',x.insurancePhone||'','tel')+field('เลขกรมธรรม์','policy',x.policy||''))}break;case'sosphrase':{const x=sosPhrases[+b.dataset.index];$('#modal').close();modal(x[0],`<p class="jp sos-jp">${x[1]}</p><p>${x[2]}</p>${btn('กลับ SOS','sos')}`)}break;case'flightedit':{const x=T().flight||{};formModal('เที่ยวบินของฉัน','flightform',field('เลขเที่ยวบิน เช่น XX123','number',x.number||'','text','required maxlength="16"')+field('วันเดินทาง','date',x.date||T().start,'date','required')+'<p>ตรวจสถานะล่าสุดจากสายการบินหรือสนามบิน ข้อมูลนี้เป็นเลขเที่ยวบินที่คุณบันทึก</p>')}break;case'manualstatus':{const k=b.dataset.key;formModal('บันทึกผลตรวจจากแหล่งทางการ','manualstatusform',`<input type="hidden" name="key" value="${esc(k)}">${textarea('ผลตรวจ เช่น เที่ยวบิน XX123 คาดว่าออก 18:50 ล่าช้า 30 นาที','text',T().liveNotes?.[k]?.text||'')}<p class="note">บันทึกเฉพาะที่ตรวจเห็นจริง เวลาบันทึกจะถูกระบุอัตโนมัติ</p>`)}break;case'placeedit':editPlace(id);break;case'placesample':editPlace('',b.dataset.name);break;case'placestar':case'placevisited':commitState((s,t)=>{const x=t.places.find(x=>x.id===id);if(x)x[a==='placestar'?'star':'visited']=!x[a==='placestar'?'star':'visited']});render();break;case'placedelete':if(confirm('ลบสถานที่นี้จากรายการอยากไป?')){commitState((s,t)=>{t.places=t.places.filter(x=>x.id!==id)});$('#modal').close();render()}break;case'placeplan':{const x=T().places.find(x=>x.id===id);eventModal();$('#eventform [name=title]').value=x.name;$('#eventform [name=note]').value=(x.city||'')+'\n'+(x.note||'')}break;case'railmore':railMore();break;case'raillesson':{const x=railLessons[+b.dataset.index];$('#modal').close();eventModal();$('#eventform [name=title]').value=x[0];$('#eventform [name=note]').value=x[1]+'\n'+x[2]}break;case'checkupdate':await checkUpdate();break;case'applyupdate':await applyUpdate();break}}catch(err){toast(err.message||'ทำรายการไม่สำเร็จ')}},true);
document.addEventListener('submit',e=>{const f=e.target,id=f.getAttribute('id');if(!['placeform','emergencyform','flightform','manualstatusform'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f));try{commitState((s,t)=>{if(id==='placeform'){if(!v.name.trim())throw Error('กรอกชื่อสถานที่');t.places=t.places||[];const old=t.places.find(x=>x.id===v.id);if(old)Object.assign(old,{name:v.name.trim(),city:v.city,note:v.note});else t.places.push({id:uid(),name:v.name.trim(),city:v.city,note:v.note,star:false,visited:false})}if(id==='emergencyform')t.emergency=v;if(id==='flightform'){if(!v.number.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(v.date))throw Error('กรอกเที่ยวบินและวันที่');t.flight=v}if(id==='manualstatusform'){if(!['flight','rail','storm'].includes(v.key)||!v.text.trim())throw Error('กรอกผลตรวจ');t.liveNotes=t.liveNotes||{};t.liveNotes[v.key]={text:v.text.trim(),checked:nowTime()}}});$('#modal').close();render();toast('บันทึกในเครื่องแล้ว')}catch(err){toast(err.message)}},true);
// 1.0.9: Dashboard is the center tab on mobile; keep seven destinations balanced.
nav.splice(0,nav.length,['now','ตอนนี้','refresh'],['discover','ที่ควรไป','pin'],['plan','แผนเที่ยว','plan'],['home','แดชบอร์ด','home'],['travel','เดินทาง','travel'],['money','บัญชี','money'],['trip','ทริปของฉัน','trip']);
const discover=createDiscover({esc,uid,trip:T,commit:commitState,dates,today,toast,render:()=>render(),settings:()=>tripModal(),close:()=>$('#modal').close(),modal:(heading,body)=>{if($('#modal').open)$('#modal').close();modal(heading,body)}});

// === 1.0.9 itinerary controls: booking, tickets, next-leg routes, mobile ordering ===
const bookingLabels={wish:'อยากไป',planned:'ใส่แผนแล้ว',need:'ต้องจอง',booked:'จองแล้ว'};
const validBooking=new Set(Object.keys(bookingLabels));
const dayEvents=(date,source=T().events)=>source.filter(e=>e.date===date).slice().sort((a,b)=>{const ao=Number.isFinite(a.order)?a.order:1e9,bo=Number.isFinite(b.order)?b.order:1e9;if(ao!==bo)return ao-bo;return String(a.time||'99:99').localeCompare(String(b.time||'99:99'))||String(a.title).localeCompare(String(b.title))});
function resequence(date){dayEvents(date).forEach((e,i)=>e.order=i)}
function googleLeg(a,b){const q=x=>encodeURIComponent(String(x||'').trim());return `https://www.google.com/maps/dir/?api=1&origin=${q(a.title)}&destination=${q(b.title)}&travelmode=transit`}
function eventRows109(events){const list=events.slice().sort((a,b)=>{const ao=Number.isFinite(a.order)?a.order:1e9,bo=Number.isFinite(b.order)?b.order:1e9;if(ao!==bo)return ao-bo;return String(a.time||'99:99').localeCompare(String(b.time||'99:99'))});if(!list.length)return `<div class="empty">วันนี้ยังไม่มีแผน<br>เพิ่มสถานที่หรือเวลานัดหมายได้เลย</div>`;return list.map((e,i)=>{const next=list[i+1],status=validBooking.has(e.bookingStatus)?e.bookingStatus:'planned',route=e.routeToNext&&next&&e.routeToNext.destinationId===next.id?e.routeToNext:null;return `<article class="event event-card ${e.done?'done':''}"><time>${esc(e.time||'—')}</time><span class="dot"></span><div class="event-main"><div class="event-heading"><h3>${esc(e.title)}</h3><div class="event-state"><span class="booking-chip booking-${status}">${bookingLabels[status]}</span>${e.entryTime?`<span class="entry-chip">เข้า ${esc(e.entryTime)}</span>`:''}${e.done?'<span class="entry-chip done-chip">ไปแล้ว ✓</span>':''}</div></div>${e.note?`<p>${esc(e.note)}</p>`:''}${route?`<div class="leg-note"><b>วิธีไปจุดถัดไป</b><span>${esc(route.text)}</span></div>`:''}${e.ticketFileId?`<div class="ticket-line">🎟 ${esc(e.ticketName||'ตั๋วที่แนบไว้')} ${btn('เปิดตั๋ว','docopen','small',`data-id="${esc(e.ticketFileId)}"`)}</div>`:''}<div class="event-route-actions">${next?`<a class="btn small route-next" data-online-route href="${googleLeg(e,next)}" target="_blank" rel="noopener noreferrer">จากจุดนี้ไปจุดถัดไป ↗</a>${btn(route?'แก้วิธีเดินทาง':'บันทึกวิธีเดินทาง','routeedit','small',`data-id="${esc(e.id)}" data-next="${esc(next.id)}"`)}`:''}${e.discoverId?`<button type="button" class="btn small" data-discover="detail" data-id="${esc(e.discoverId)}">📍 สถานที่</button>`:''}</div></div><div class="event-mobile-controls">${btn('↑','eventup','small',`data-id="${esc(e.id)}" aria-label="เลื่อน ${esc(e.title)} ขึ้น" ${i===0?'disabled':''}`)}${btn('↓','eventdown','small',`data-id="${esc(e.id)}" aria-label="เลื่อน ${esc(e.title)} ลง" ${i===list.length-1?'disabled':''}`)}${btn('ย้ายวัน','eventmove','small',`data-id="${esc(e.id)}"`)}${btn(e.done?'ยังไม่ไป':'ไปแล้ว ✓','eventdone','small',`data-id="${esc(e.id)}"`)}${btn(icon('edit'),'eventedit','small',`data-id="${esc(e.id)}" aria-label="แก้ไข ${esc(e.title)}"`)}</div></article>`}).join('')}
eventRows=eventRows109;
planView=function(){const t=T(),ds=dates(t);if(!ds.includes(day))day=ds[0];const list=dayEvents(day);return title('ITINERARY','แผนเที่ยวของเรา','เรียงด้วยปุ่มบนมือถือ · เก็บเส้นทาง ตั๋ว และสถานะการจองไว้ในวันเดียวกัน',btn(icon('plus')+' เพิ่มแผน','eventedit','primary'))+`<div class="tabs plan-date-tabs">${ds.map(d=>`<button class="tab datebtn ${d===day?'active':''}" data-day="${d}">${new Intl.DateTimeFormat('th',{weekday:'short'}).format(new Date(d+'T12:00:00'))}<b>${Number(d.slice(-2))}</b></button>`).join('')}</div><div class="grid cols plan-layout"><div class="card plan-card"><div class="cardhead"><div><h2>${formatDate(day)}</h2><p class="note">${list.length} จุด · กด ↑ ↓ เพื่อจัดลำดับโดยไม่ต้องลาก</p></div><span class="pill">บันทึกในเครื่อง</span></div>${eventRows109(list)}</div><div><div class="card booking-legend"><h2>สถานะการจอง</h2><div class="booking-flow"><span>อยากไป</span><i>→</i><span>ใส่แผนแล้ว</span><i>→</i><span>ต้องจอง</span><i>→</i><span>จองแล้ว</span></div><p class="note">รายการ “อยากไป” เก็บจากหน้า ที่ควรไป · เมื่อใส่ลงวันแล้วเลือกสถานะต่อได้ในปุ่มแก้ไข</p></div><div class="card gap"><h2>สิ่งที่ยังรอยืนยัน</h2><p class="note">${t.meeting?'จุดนัดพบ: '+esc(t.meeting):'จุดนัดพบหลังออกจากสนามบินยังไม่ระบุ'}</p>${btn('เพิ่มหรือแก้ไขข้อมูลทริป','tripsettings','full')}</div><div class="card gap"><h2>เผื่อแผนเปลี่ยน</h2><p>${esc(t.backup||'บันทึกวิธีติดต่อ จุดนัดสำรอง หรือสิ่งที่จะทำหากพลาดรถไว้ที่นี่')}</p>${btn('แก้ไขแผนสำรอง','tripsettings')}</div></div></div>`+placesView()};
eventModal=function(id){const e=T().events.find(x=>x.id===id)||{date:day||T().start,time:'',title:'',note:'',done:false,bookingStatus:'planned',entryTime:''},status=validBooking.has(e.bookingStatus)?e.bookingStatus:'planned';formModal('แผนการเดินทาง','eventform',`<input hidden name="id" value="${esc(id||'')}">${field('กิจกรรม / สถานที่','title',e.title,'text','required maxlength="140"')}<div class="grid two formgrid">${field('วันที่','date',e.date,'date','required')}${field('เวลาในแผน (เว้นว่างได้)','time',e.time,'time')}</div>${select('สถานะการจอง','bookingStatus',Object.entries(bookingLabels).map(([v,l])=>[v,l]),status)}${field('เวลาเข้าชมตามตั๋ว (ถ้ามี)','entryTime',e.entryTime||'','time')}${textarea('หมายเหตุสถานที่','note',e.note||'')}<div class="ticket-editor"><b>🎟 ตั๋ว / ใบจอง</b>${id?(e.ticketFileId?`<p>${esc(e.ticketName||'แนบตั๋วแล้ว')}</p><div class="flex">${btn('เปิดตั๋ว','docopen','small',`data-id="${esc(e.ticketFileId)}"`)}${btn('เปลี่ยนไฟล์','ticketadd','small',`data-id="${esc(id)}"`)}${btn('เอาตั๋วออก','ticketremove','small danger',`data-id="${esc(id)}"`)}</div>`:`<p class="note">แนบภาพหรือ PDF สูงสุด 8 MB เพื่อเปิดจากเครื่องนี้ได้</p>${btn('แนบตั๋ว','ticketadd','small',`data-id="${esc(id)}"`)}`):'<p class="note">บันทึกแผนก่อน 1 ครั้ง แล้วเปิดแก้ไขเพื่อแนบตั๋ว</p>'}</div><label class="checkboxlabel"><input type="checkbox" name="done" ${e.done?'checked':''}>ทำแล้ว / ไปแล้ว</label>${id?btn('ลบแผนนี้','eventdelete','danger',`data-id="${esc(id)}"`):''}`)};
let pendingTicketEvent='';
const fullDate109=d=>new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'));
function routeEdit(id,nextId){const e=T().events.find(x=>x.id===id),n=T().events.find(x=>x.id===nextId);if(!e||!n)return;const current=e.routeToNext?.destinationId===n.id?e.routeToNext.text:'';formModal('วิธีเดินทางไปจุดถัดไป','routeform',`<input type="hidden" name="id" value="${esc(e.id)}"><input type="hidden" name="next" value="${esc(n.id)}"><p><b>${esc(e.title)}</b> → <b>${esc(n.title)}</b></p>${textarea('บันทึกไว้อ่านออฟไลน์ เช่น JR Yamanote → ลง Shibuya → ทางออก Hachiko','text',current)}<p class="note">ปุ่ม Google Maps ใช้เน็ต แต่ข้อความที่บันทึกตรงนี้เปิดอ่านออฟไลน์ได้</p>`)}
function moveEvent(id,dir){const e=T().events.find(x=>x.id===id);if(!e)return;const list=dayEvents(e.date);const i=list.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];list.forEach((x,k)=>x.order=k);list.forEach(x=>x.routeToNext=null);save();render()}
document.addEventListener('click',async e=>{const online=e.target.closest('[data-online-route]');if(online&&!navigator.onLine){e.preventDefault();e.stopImmediatePropagation();toast('Google Maps ต้องใช้อินเทอร์เน็ต · วิธีเดินทางที่บันทึกไว้อ่านออฟไลน์ได้');return}const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(!['eventup','eventdown','eventmove','eventdone','routeedit','ticketadd','ticketremove','eventdelete','docdelete'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();const id=b.dataset.id;if(a==='docdelete'){if(confirm('ลบไฟล์นี้จากเครื่อง?')){const refs=T().events.filter(x=>x.ticketFileId===id);await dbCall('delete',id);refs.forEach(x=>{delete x.ticketFileId;delete x.ticketName});S.docRevision=Date.now();save();render();toast(refs.length?'ลบไฟล์และนำออกจากแผนแล้ว':'ลบไฟล์แล้ว')}return}const ev=T().events.find(x=>x.id===id);if(!ev)return;if(a==='eventup'||a==='eventdown'){moveEvent(id,a==='eventup'?-1:1);return}if(a==='eventdone'){ev.done=!ev.done;save();render();return}if(a==='eventmove'){formModal('ย้ายไปวันอื่น','eventmoveform',`<input type="hidden" name="id" value="${esc(id)}">${select('เลือกวัน','date',dates(T()).map(d=>[d,fullDate109(d)]),ev.date)}<p class="note">รายการจะถูกวางท้ายวันใหม่ แล้วใช้ ↑ ↓ จัดตำแหน่งต่อได้</p>`);return}if(a==='routeedit'){routeEdit(id,b.dataset.next);return}if(a==='ticketadd'){pendingTicketEvent=id;$('#ticketfile').click();return}if(a==='ticketremove'){if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});delete ev.ticketFileId;delete ev.ticketName;save();$('#modal').close();render();toast('เอาตั๋วออกแล้ว');return}if(a==='eventdelete'){if(confirm('ลบแผนนี้?')){if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});T().events=T().events.filter(x=>x.id!==id);resequence(ev.date);save();$('#modal').close();render()}}},true);
document.addEventListener('submit',e=>{const f=e.target,id=f.getAttribute('id');if(!['eventform','routeform','eventmoveform'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f)),t=T();try{if(id==='routeform'){const ev=t.events.find(x=>x.id===v.id),n=t.events.find(x=>x.id===v.next);if(!ev||!n)throw Error('ไม่พบจุดในแผน');ev.routeToNext={destinationId:n.id,text:String(v.text||'').trim()};save();$('#modal').close();render();toast('บันทึกวิธีเดินทางไว้ออฟไลน์แล้ว');return}if(id==='eventmoveform'){const ev=t.events.find(x=>x.id===v.id);if(!ev||!dates(t).includes(v.date))throw Error('เลือกวันในทริป');const old=ev.date;ev.date=v.date;ev.order=dayEvents(v.date).length;ev.routeToNext=null;resequence(old);resequence(v.date);day=v.date;save();$('#modal').close();render();toast('ย้ายวันแล้ว');return}const old=t.events.find(x=>x.id===v.id),wasDate=old?.date;const state=validBooking.has(v.bookingStatus)?v.bookingStatus:'planned';const ev={...(old||{}),id:v.id||uid(),title:String(v.title||'').trim(),date:v.date,time:v.time||'',note:v.note||'',done:!!v.done,bookingStatus:state,entryTime:v.entryTime||''};if(!ev.title)throw Error('กรอกกิจกรรม / สถานที่');if(Math.abs((new Date(v.date)-new Date(t.start))/864e5)>89)throw Error('แผนต้องอยู่ภายในช่วง 90 วันของทริป');if(v.date<t.start||v.date>t.end){t.start=v.date<t.start?v.date:t.start;t.end=v.date>t.end?v.date:t.end}if(old){Object.assign(old,ev);if(wasDate!==v.date){old.order=dayEvents(v.date).length;old.routeToNext=null;resequence(wasDate)}}else{ev.order=dayEvents(v.date).length;t.events.push(ev)}resequence(v.date);day=v.date;if(!save())throw Error('พื้นที่บันทึกไม่พร้อม');$('#modal').close();render();toast('บันทึกแผนแล้ว')}catch(err){toast(err.message||'บันทึกไม่สำเร็จ')}},true);
$('#ticketfile')?.addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';const eventId=pendingTicketEvent;pendingTicketEvent='';if(!f||!eventId)return;if(f.size>8*1024*1024){toast('ไฟล์ต้องไม่เกิน 8 MB');return}if(!/^(image\/(png|jpeg|webp|gif|heic|heif)|application\/pdf)$/.test(f.type)){toast('รองรับภาพหรือ PDF');return}const ev=T().events.find(x=>x.id===eventId);if(!ev)return;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});const fileId=uid();await dbCall('put',{id:fileId,trip:T().id,event:eventId,kind:'ticket',name:f.name,type:f.type,data});ev.ticketFileId=fileId;ev.ticketName=f.name;S.docRevision=Date.now();save();$('#modal').close();render();toast('แนบตั๋วไว้ในเครื่องแล้ว')}catch{toast('เก็บตั๋วไม่ได้ พื้นที่อาจไม่เพียงพอ')}});

save();render();
